// ─── CYCLE HELPERS ───────────────────────────────────────────
const SEASON_START_MONTH = 8; // Agosto = inicio de temporada

const getCycles = (dateStr, seasonStart) => {
  const d = new Date(dateStr + "T12:00");
  const year = d.getFullYear();
  const month = d.getMonth() + 1; // 1-12

  // Macrociclo: temporada (año inicio)
  const seasonYear = month >= SEASON_START_MONTH ? year : year - 1;
  const macro = `${seasonYear}-${seasonYear+1}`;

  // Mesociclo: mes dentro de la temporada (1=Ago, 2=Sep... 12=Jul)
  const monthsFromStart = month >= SEASON_START_MONTH
    ? month - SEASON_START_MONTH + 1
    : month + (12 - SEASON_START_MONTH) + 1;
  const meso = monthsFromStart;

  // Microciclo: semana desde el inicio de temporada del equipo
  let micro = 1;
  if(seasonStart) {
    const start = new Date(seasonStart + "T12:00");
    const msPerWeek = 7 * 24 * 60 * 60 * 1000;
    // Get Monday of start week
    const startDay = start.getDay()||7;
    const startMonday = new Date(start.getTime() - (startDay-1)*86400000);
    // Get Monday of current week
    const curDay = d.getDay()||7;
    const curMonday = new Date(d.getTime() - (curDay-1)*86400000);
    const weeksDiff = Math.round((curMonday - startMonday) / msPerWeek);
    micro = Math.max(1, weeksDiff + 1);
  } else {
    // Fallback: week within season (week of year - week of season start)
    const seasonStartDate = new Date(`${seasonYear}-08-01T12:00`);
    const startDay = seasonStartDate.getDay()||7;
    const startMonday = new Date(seasonStartDate.getTime() - (startDay-1)*86400000);
    const curDay = d.getDay()||7;
    const curMonday = new Date(d.getTime() - (curDay-1)*86400000);
    micro = Math.max(1, Math.round((curMonday - startMonday) / (7*24*60*60*1000)) + 1);
  }

  return { macro, meso, micro, mesoLabel: fmtMonth(dateStr.slice(0,7)) };
};

// ─── TREND HELPERS ───────────────────────────────────────────
const calcTrend = (ratings) => {
  // ratings: array of "green"/"yellow"/"red" ordered by date (oldest first)
  if(!ratings||ratings.length===0) return null;
  if(ratings.length===1) return ratings[0];
  const val = r => r==="green"?3:r==="yellow"?2:1;
  const half = Math.ceil(ratings.length/2);
  const first = ratings.slice(0,half);
  const last  = ratings.slice(-half);
  const avgFirst = first.reduce((a,r)=>a+val(r),0)/first.length;
  const avgLast  = last.reduce((a,r)=>a+val(r),0)/last.length;
  const diff = avgLast - avgFirst;
  if(diff >= 0.5) return "green";
  if(diff <= -0.5) return "red";
  // No clear trend — use last average
  if(avgLast >= 2.5) return "green";
  if(avgLast <= 1.5) return "red";
  return "yellow";
};

const getMonthRatings = (playerId, sessions, matches) => {
  // Returns {month: [ratings]} for a player
  const byMonth = {};
  [...(sessions||[]).map(s=>({...s,stype:"training"})),...(matches||[]).map(s=>({...s,stype:"match"}))].forEach(s=>{
    const r=s.ratings?.[playerId]; if(!r)return;
    const mk=s.date.slice(0,7);
    if(!byMonth[mk])byMonth[mk]=[];
    byMonth[mk].push(r);
  });
  return byMonth;
};

const getQuarterTrend = (playerId, sessions, matches, quarterMonths) => {
  const allRatings=[];
  [...(sessions||[]).map(s=>({...s,stype:"training"})),...(matches||[]).map(s=>({...s,stype:"match"}))].filter(s=>quarterMonths.includes(s.date.slice(0,7))).sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>{
    const r=s.ratings?.[playerId]; if(r)allRatings.push(r);
  });
  return {trend:calcTrend(allRatings), count:allRatings.length, ratings:allRatings};
};


