// ─── GOOGLE LOGIN SCREEN ──────────────────────────────────────
function GoogleLogin({onLogin}){
  const [email,setEmail]=useState("");
  const [pass,setPass]=useState("");
  const [err,setErr]=useState("");
  const [loading,setLoading]=useState(false);
  const submit=async()=>{
    if(!email||!pass)return;
    setLoading(true);setErr("");
    try{ await onLogin(email,pass); }
    catch(e){ setErr("Email o contraseña incorrectos"); setLoading(false); }
  };
  return <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:"#0d0f18",padding:24}}>
    <div style={{background:"#13161f",border:"1px solid #252836",borderRadius:22,padding:"44px 36px",width:"100%",maxWidth:380}}>
      <div style={{textAlign:"center",marginBottom:32}}>
        <div style={{width:56,height:56,background:"#2563eb",borderRadius:16,display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,margin:"0 auto 16px"}}>⚽</div>
        <div style={{fontSize:22,fontWeight:700,marginBottom:6}}>Canet F.C.</div>
        <div style={{fontSize:13,color:"#6b7280"}}>Gestión de Asistencia</div>
      </div>
      <div style={{marginBottom:12}}>
        <label style={{fontSize:11,fontWeight:600,color:"#9ca3af",textTransform:"uppercase",letterSpacing:".5px",display:"block",marginBottom:5}}>Email</label>
        <input style={{background:"#1c1f2e",border:"1px solid #252836",borderRadius:9,padding:"10px 12px",color:"#e2e4f0",fontSize:14,width:"100%",outline:"none"}}
          type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="tu@email.com"/>
      </div>
      <div style={{marginBottom:20}}>
        <label style={{fontSize:11,fontWeight:600,color:"#9ca3af",textTransform:"uppercase",letterSpacing:".5px",display:"block",marginBottom:5}}>Contraseña</label>
        <input style={{background:"#1c1f2e",border:"1px solid #252836",borderRadius:9,padding:"10px 12px",color:"#e2e4f0",fontSize:14,width:"100%",outline:"none"}}
          type="password" value={pass} onChange={e=>setPass(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()} placeholder="••••••••"/>
      </div>
      {err&&<div style={{color:"#ef4444",fontSize:13,marginBottom:12,textAlign:"center"}}>{err}</div>}
      <button onClick={submit} disabled={loading} style={{width:"100%",background:"#2563eb",border:"none",borderRadius:12,padding:"14px",fontSize:15,fontWeight:600,color:"white",cursor:"pointer"}}>
        {loading?"Entrando...":"Entrar"}
      </button>
      <div style={{fontSize:11,color:"#4b5563",marginTop:14,textAlign:"center"}}>Solo usuarios autorizados por el club</div>
    </div>
  </div>;
}

// ─── ALINEACION TAB ───────────────────────────────────────────
function AlineacionTab({session,team,updateTeam}){
  const alin=session.alineacion||{};
  const isF7=(team.format==="F7")||["S8","S9","S10","S11","Alevín Femenino"].includes(team.category);
  const allFormations=isF7?FORMATIONS_F7:FORMATIONS_F11;
  const [selFormation,setSelFormation]=useState(alin.formation||Object.keys(allFormations)[0]);
  const [showSelector,setShowSelector]=useState(null); // position id being assigned
  const formation=allFormations[selFormation];
  const assignments=alin.assignments||{}; // positionId -> playerId
  const suplentes=alin.suplentes||[];
  const players=team.players||[];
  const conv=session.convocados||[];
  const convPlayers=players.filter(p=>conv.includes(p.id));
  const assignedIds=Object.values(assignments);
  const availableSubs=convPlayers.filter(p=>!assignedIds.includes(p.id)&&!suplentes.includes(p.id));
  const supPlayers=convPlayers.filter(p=>suplentes.includes(p.id));

  const save=(updates)=>{
    updateTeam(team.id,t=>({...t,matches:t.matches.map(m=>m.id===session.id?{...m,alineacion:{...m.alineacion,...updates}}:m)}));
  };

  const setFormation=(f)=>{ setSelFormation(f); save({formation:f,assignments:{},suplentes:[]}); };
  const assignPlayer=(posId,playerId)=>{ 
    const newA={...assignments};
    // Remove player from other positions
    Object.keys(newA).forEach(k=>{ if(newA[k]===playerId) delete newA[k]; });
    if(playerId) newA[posId]=playerId; else delete newA[posId];
    // Remove from suplentes if assigned
    const newS=suplentes.filter(id=>id!==playerId);
    save({assignments:newA,suplentes:newS});
    setShowSelector(null);
  };
  const toggleSuplente=(pid)=>{
    if(assignedIds.includes(pid)) return; // already in field
    const newS=suplentes.includes(pid)?suplentes.filter(x=>x!==pid):[...suplentes,pid];
    save({suplentes:newS});
  };

  const getPlayer=(id)=>players.find(p=>p.id===id);

  return <div>
    {/* Formation selector */}
    <div className="card" style={{padding:12,marginBottom:12}}>
      <label className="flabel" style={{display:"block",marginBottom:6}}>Formación</label>
      <div style={{display:"flex",flexWrap:"wrap",gap:5}}>
        {Object.entries(allFormations).map(([key,f])=><button key={key} className="btn btn-sm"
          style={{background:selFormation===key?"#2563eb":"#1c1f2e",color:selFormation===key?"white":"#9ca3af",border:`1px solid ${selFormation===key?"#2563eb":"#252836"}`,fontSize:11}}
          onClick={()=>setFormation(key)}>{f.label}</button>)}
      </div>
    </div>

    {/* Pitch */}
    <div className="card" style={{padding:10,marginBottom:12}}>
      <div style={{position:"relative",width:"100%",paddingBottom:"150%",background:"#1a3a1a",borderRadius:10,overflow:"hidden",border:"2px solid #2a5a2a"}}>
        {/* Field markings */}
        <svg style={{position:"absolute",inset:0,width:"100%",height:"100%"}} viewBox="0 0 100 150" preserveAspectRatio="none">
          <rect x="5" y="5" width="90" height="140" fill="none" stroke="#2a5a2a" strokeWidth="0.8"/>
          <line x1="5" y1="75" x2="95" y2="75" stroke="#2a5a2a" strokeWidth="0.5"/>
          <circle cx="50" cy="75" r="10" fill="none" stroke="#2a5a2a" strokeWidth="0.5"/>
          <rect x="25" y="5" width="50" height="20" fill="none" stroke="#2a5a2a" strokeWidth="0.5"/>
          <rect x="35" y="5" width="30" height="10" fill="none" stroke="#2a5a2a" strokeWidth="0.5"/>
          <rect x="25" y="125" width="50" height="20" fill="none" stroke="#2a5a2a" strokeWidth="0.5"/>
          <rect x="35" y="135" width="30" height="10" fill="none" stroke="#2a5a2a" strokeWidth="0.5"/>
        </svg>
        {/* Players on field */}
        {formation&&formation.positions.map(pos=>{
          const pid=assignments[pos.id];
          const player=pid?getPlayer(pid):null;
          return <div key={pos.id} style={{position:"absolute",left:`${pos.x}%`,top:`${pos.y}%`,transform:"translate(-50%,-50%)",textAlign:"center",zIndex:10,cursor:"pointer"}}
            onClick={()=>setShowSelector(showSelector===pos.id?null:pos.id)}>
            <div style={{width:36,height:36,borderRadius:"50%",background:player?"#2563eb":"rgba(255,255,255,0.15)",border:`2px solid ${player?"#2563eb":"rgba(255,255,255,0.4)"}`,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto",fontSize:11,fontWeight:700,color:"white",boxShadow:player?"0 2px 8px #2563eb66":"none"}}>
              {player?`#${player.number||player.name[0]}`:"＋"}
            </div>
            <div style={{fontSize:9,color:"white",marginTop:2,textShadow:"0 1px 3px #000",maxWidth:50,lineHeight:1.2}}>
              {player?player.name.split(" ")[0]:pos.name}
            </div>
            {/* Player selector dropdown */}
            {showSelector===pos.id&&<div style={{position:"absolute",top:"100%",left:"50%",transform:"translateX(-50%)",background:"#13161f",border:"1px solid #252836",borderRadius:9,padding:6,zIndex:100,minWidth:140,maxHeight:160,overflowY:"auto",boxShadow:"0 4px 20px #000a"}}>
              <div style={{fontSize:10,color:"#6b7280",padding:"2px 4px",marginBottom:4}}>Asignar jugador</div>
              {player&&<div style={{padding:"5px 8px",borderRadius:6,cursor:"pointer",fontSize:12,color:"#ef4444",marginBottom:3}} onClick={()=>assignPlayer(pos.id,null)}>✕ Quitar</div>}
              {convPlayers.filter(p=>!suplentes.includes(p.id)).map(p=><div key={p.id} style={{padding:"5px 8px",borderRadius:6,cursor:"pointer",fontSize:12,background:assignments[pos.id]===p.id?"#2563eb18":"transparent",color:assignments[pos.id]===p.id?"#2563eb":"#e2e4f0",fontWeight:assignedIds.includes(p.id)&&assignments[pos.id]!==p.id?400:600}}
                onClick={()=>assignPlayer(pos.id,p.id)}>
                {p.number?`#${p.number} `:""}{p.name.split(" ")[0]}
                {assignedIds.includes(p.id)&&assignments[pos.id]!==p.id&&<span style={{color:"#6b7280",fontSize:10}}> (en campo)</span>}
              </div>)}
            </div>}
          </div>;
        })}
      </div>
    </div>

    {/* Suplentes */}
    <div className="card">
      <div className="card-title">Suplentes</div>
      {convPlayers.length===0&&<div style={{fontSize:12,color:"#4b5563"}}>Define primero la convocatoria</div>}
      <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
        {convPlayers.filter(p=>!assignedIds.includes(p.id)).map(p=><button key={p.id} className="btn btn-sm"
          style={{background:suplentes.includes(p.id)?"#f9731618":"#1c1f2e",color:suplentes.includes(p.id)?"#fb923c":"#9ca3af",border:`1px solid ${suplentes.includes(p.id)?"#f9731630":"#252836"}`}}
          onClick={()=>toggleSuplente(p.id)}>
          {p.number?`#${p.number} `:""}{p.name.split(" ")[0]}
        </button>)}
      </div>
      {availableSubs.length>0&&!assignedIds.length&&<div style={{fontSize:11,color:"#4b5563",marginTop:8}}>Toca un jugador para marcarlo como suplente</div>}
    </div>

    {/* Summary */}
    {(Object.keys(assignments).length>0||suplentes.length>0)&&<div className="card" style={{marginTop:12}}>
      <div className="card-title">Resumen</div>
      <div style={{fontSize:13,color:"#6b7280",marginBottom:6}}>Titulares: {Object.keys(assignments).length}/{formation?.positions.length||11} · Suplentes: {suplentes.length}</div>
      {formation?.positions.filter(p=>!assignments[p.id]).length>0&&<div style={{fontSize:12,color:"#f97316"}}>⚠️ Posiciones sin asignar: {formation.positions.filter(p=>!assignments[p.id]).map(p=>p.name).join(", ")}</div>}
    </div>}
  </div>;
}

// ─── INCIDENCIAS BLOCK ────────────────────────────────────────
function IncidenciasBlock({session,team,updateTeam,isMatch}){
  const [showForm,setShowForm]=useState(false);
  const [form,setForm]=useState({playerId:"",type:"",severity:"Leve",description:"",injuryZoneGroup:"",injuryZone:"",injurySide:"",injuryGrade:"",mechanism:""});
  const incidencias=session.incidencias||[];
  const players=team.players||[];

  const save=()=>{
    if(!form.type)return;
    const inc={id:genId(),date:session.date,...form,injuryZoneGroup:form.injuryZoneGroup||"",injuryZone:form.injuryZone||"",mechanism:form.mechanism||"",sessionId:session.id,sessionType:isMatch?"match":"training"};
    const update=i=>{
      const newInc=[...(i.incidencias||[]),inc];
      if(isMatch) return{...i,matches:i.matches.map(m=>m.id===session.id?{...m,incidencias:newInc}:m)};
      return{...i,sessions:i.sessions.map(s=>s.id===session.id?{...s,incidencias:newInc}:s)};
    };
    updateTeam(team.id,update);
    setForm({playerId:"",type:"",severity:"Leve",description:"",injuryZoneGroup:"",injuryZone:"",injurySide:"",injuryGrade:"",mechanism:""});
    setShowForm(false);
  };

  const remove=(id)=>{
    const update=i=>{
      const newInc=(i.incidencias||[]).filter(x=>x.id!==id);
      if(isMatch) return{...i,matches:i.matches.map(m=>m.id===session.id?{...m,incidencias:(m.incidencias||[]).filter(x=>x.id!==id)}:m)};
      return{...i,sessions:i.sessions.map(s=>s.id===session.id?{...s,incidencias:(s.incidencias||[]).filter(x=>x.id!==id)}:s)};
    };
    updateTeam(team.id,update);
  };

  return <div style={{marginTop:14}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
      <div style={{fontSize:13,fontWeight:700}}>⚡ Incidencias {incidencias.length>0&&<span style={{background:"#ef444420",color:"#ef4444",borderRadius:20,padding:"1px 7px",fontSize:11,marginLeft:5}}>{incidencias.length}</span>}</div>
      <button className="btn btn-sm" style={{background:"#ef444415",color:"#ef4444",border:"1px solid #ef444430"}} onClick={()=>setShowForm(!showForm)}>+ Incidencia</button>
    </div>

    {showForm&&<div className="card" style={{marginBottom:10,borderColor:"#ef444428"}}>
      <div className="frow" style={{marginBottom:8}}>
        <div className="fg"><label className="flabel">Jugador (opcional)</label>
          <select className="fselect" style={{fontSize:12}} value={form.playerId} onChange={e=>setForm({...form,playerId:e.target.value})}>
            <option value="">Sin jugador específico</option>
            {players.map(p=><option key={p.id} value={p.id}>{p.number?`#${p.number} `:""}{p.name}</option>)}
          </select>
        </div>
        <div className="fg" style={{maxWidth:100}}><label className="flabel">Gravedad</label>
          <select className="fselect" style={{fontSize:12}} value={form.severity} onChange={e=>setForm({...form,severity:e.target.value})}>
            {INCIDENCE_SEVERITY.map(s=><option key={s} value={s}>{s}</option>)}
          </select>
        </div>
      </div>
      <div className="fg" style={{marginBottom:8}}>
        <label className="flabel">Tipo de incidencia</label>
        <div style={{display:"flex",flexWrap:"wrap",gap:4,marginTop:4}}>
          {INCIDENCE_TYPES.map(t=><button key={t.id} className="btn btn-xs"
            style={{background:form.type===t.id?t.color+"22":"#13161f",color:form.type===t.id?t.color:"#6b7280",border:`1px solid ${form.type===t.id?t.color:"#252836"}`}}
            onClick={()=>setForm({...form,type:t.id,injuryZoneGroup:"",injuryZone:""})}>
            {t.icon} {t.label}</button>)}
        </div>
      </div>
      {(form.type==="lesion"||form.type==="sobrecarga"||form.type==="golpe")&&<div style={{background:"#ef444410",border:"1px solid #ef444425",borderRadius:9,padding:10,marginBottom:8}}>
        <label className="flabel" style={{display:"block",marginBottom:6}}>Zona lesionada</label>
        <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:8}}>
          {Object.keys(INJURY_DETAIL).map(g=><button key={g} className="btn btn-xs"
            style={{background:form.injuryZoneGroup===g?"#ef444422":"#13161f",color:form.injuryZoneGroup===g?"#ef4444":"#6b7280",border:`1px solid ${form.injuryZoneGroup===g?"#ef4444":"#252836"}`}}
            onClick={()=>setForm({...form,injuryZoneGroup:g,injuryZone:"",injurySide:"",injuryGrade:""})}>{g}</button>)}
        </div>
        {form.injuryZoneGroup&&INJURY_DETAIL[form.injuryZoneGroup]&&<>
          <div style={{display:"flex",flexWrap:"wrap",gap:4,marginBottom:7}}>
            {INJURY_DETAIL[form.injuryZoneGroup].zones.map(z=><button key={z} className="btn btn-xs"
              style={{background:form.injuryZone===z?"#f9731622":"#13161f",color:form.injuryZone===z?"#fb923c":"#9ca3af",border:`1px solid ${form.injuryZone===z?"#f97316":"#252836"}`}}
              onClick={()=>setForm({...form,injuryZone:z})}>{z}</button>)}
          </div>
          <div className="frow" style={{marginBottom:7}}>
            <div className="fg"><label className="flabel">Lado</label>
              <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>
                {INJURY_DETAIL[form.injuryZoneGroup].sides.map(s=><button key={s} className="btn btn-xs"
                  style={{background:form.injurySide===s?"#2563eb22":"#13161f",color:form.injurySide===s?"#2563eb":"#6b7280",border:`1px solid ${form.injurySide===s?"#2563eb":"#252836"}`}}
                  onClick={()=>setForm({...form,injurySide:s})}>{s}</button>)}
              </div>
            </div>
            <div className="fg"><label className="flabel">Grado</label>
              <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:4}}>
                {INJURY_DETAIL[form.injuryZoneGroup].grades.map(g=><button key={g} className="btn btn-xs"
                  style={{background:form.injuryGrade===g?"#8b5cf622":"#13161f",color:form.injuryGrade===g?"#a78bfa":"#6b7280",border:`1px solid ${form.injuryGrade===g?"#8b5cf6":"#252836"}`}}
                  onClick={()=>setForm({...form,injuryGrade:g})}>{g}</button>)}
              </div>
            </div>
          </div>
        </>}
        <div className="fg">
          <label className="flabel">Mecanismo lesional</label>
          <input className="finput" style={{fontSize:12}} value={form.mechanism||""} onChange={e=>setForm({...form,mechanism:e.target.value})} placeholder="Ej: Sprint sin contacto, entrada rival, disparo..."/>
        </div>
      </div>}
      <div className="fg" style={{marginBottom:8}}>
        <label className="flabel">Descripción / Observaciones</label>
        <textarea className="ftextarea" style={{minHeight:52}} value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Describe lo ocurrido..."/>
      </div>
      <div style={{display:"flex",gap:7}}>
        <button className="btn btn-primary btn-sm" onClick={save} disabled={!form.type}>Guardar</button>
        <button className="btn btn-outline btn-sm" onClick={()=>setShowForm(false)}>Cancelar</button>
      </div>
    </div>}

    {incidencias.map(inc=>{
      const itype=INCIDENCE_TYPES.find(t=>t.id===inc.type);
      const player=players.find(p=>p.id===inc.playerId);
      const sevColor=inc.severity==="Grave"?"#ef4444":inc.severity==="Moderada"?"#f97316":"#eab308";
      return <div key={inc.id} style={{background:"#1c1f2e",border:`1px solid ${itype?.color||"#252836"}28`,borderRadius:9,padding:"10px 12px",marginBottom:7}}>
        <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:3}}>
              <span style={{fontSize:13,fontWeight:700,color:itype?.color||"#e2e4f0"}}>{itype?.icon} {itype?.label||inc.type}</span>
              <span style={{background:sevColor+"20",color:sevColor,border:`1px solid ${sevColor}30`,borderRadius:20,padding:"1px 7px",fontSize:10,fontWeight:600}}>{inc.severity}</span>
            </div>
            {player&&<div style={{fontSize:11,color:"#6b7280",marginBottom:3}}>👤 {player.name}</div>}
            {inc.description&&<div style={{fontSize:12,color:"#9ca3af"}}>{inc.description}</div>}
          </div>
          <button className="btn btn-danger btn-xs" onClick={()=>remove(inc.id)}>✕</button>
        </div>
      </div>;
    })}
    {incidencias.length===0&&!showForm&&<div style={{fontSize:12,color:"#4b5563",padding:"6px 0"}}>Sin incidencias registradas</div>}
  </div>;
}

// ─── INCIDENCIAS GLOBALES (coordinador) ───────────────────────
function IncidenciasGlobalView({teams}){
  const [filterSev,setFilterSev]=useState("all");
  const [filterTeam,setFilterTeam]=useState("all");
  const all=[];
  teams.forEach(team=>{
    [...(team.sessions||[]),...(team.matches||[])].forEach(s=>{
      (s.incidencias||[]).forEach(inc=>{
        const itype=INCIDENCE_TYPES.find(t=>t.id===inc.type);
        const player=(team.players||[]).find(p=>p.id===inc.playerId);
        all.push({...inc,teamName:team.name,teamCategory:team.category,itype,playerName:player?.name,sessionDate:s.date,sessionType:s.type||"training"});
      });
    });
  });
  all.sort((a,b)=>b.sessionDate.localeCompare(a.sessionDate));
  const filtered=all.filter(i=>(filterSev==="all"||i.severity===filterSev)&&(filterTeam==="all"||i.teamName===filterTeam));
  const graves=all.filter(i=>i.severity==="Grave").length;

  return <div>
    <div className="sec-title">⚡ Incidencias del Club</div>
    {graves>0&&<div className="alert alert-warn" style={{marginBottom:14}}>🔴 {graves} incidencia{graves>1?"s":""} grave{graves>1?"s":""} registrada{graves>1?"s":""}</div>}
    <div className="frow" style={{marginBottom:14}}>
      <div className="fg"><label className="flabel">Equipo</label>
        <select className="fselect" value={filterTeam} onChange={e=>setFilterTeam(e.target.value)}>
          <option value="all">Todos</option>
          {teams.map(t=><option key={t.id} value={t.name}>{t.name}</option>)}
        </select>
      </div>
      <div className="fg" style={{maxWidth:130}}><label className="flabel">Gravedad</label>
        <select className="fselect" value={filterSev} onChange={e=>setFilterSev(e.target.value)}>
          <option value="all">Todas</option>
          {INCIDENCE_SEVERITY.map(s=><option key={s} value={s}>{s}</option>)}
        </select>
      </div>
    </div>
    {filtered.length===0&&<div className="empty"><div className="empty-icon">✅</div>Sin incidencias</div>}
    {filtered.map((inc,i)=>{
      const sevColor=inc.severity==="Grave"?"#ef4444":inc.severity==="Moderada"?"#f97316":"#eab308";
      return <div key={i} className="card-sm" style={{marginBottom:8,borderColor:inc.severity==="Grave"?"#ef444430":"#252836"}}>
        <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap",marginBottom:4}}>
              <span style={{fontSize:13,fontWeight:700,color:inc.itype?.color||"#e2e4f0"}}>{inc.itype?.icon} {inc.itype?.label||inc.type}</span>
              <span style={{background:sevColor+"20",color:sevColor,border:`1px solid ${sevColor}30`,borderRadius:20,padding:"1px 7px",fontSize:10,fontWeight:600}}>{inc.severity}</span>
            </div>
            <div style={{fontSize:11,color:"#6b7280"}}>{inc.teamName} · {fmtDate(inc.sessionDate)} · {inc.sessionType==="match"?"Partido":"Entreno"}</div>
            {inc.playerName&&<div style={{fontSize:11,color:"#9ca3af",marginTop:2}}>👤 {inc.playerName}</div>}
            {inc.injuryZone&&<div style={{fontSize:11,color:"#f97316",marginTop:2}}>📍 {inc.injuryZoneGroup} · {inc.injuryZone}{inc.injurySide?` · ${inc.injurySide}`:""}{inc.injuryGrade?` (${inc.injuryGrade})`:""}</div>}
            {inc.mechanism&&<div style={{fontSize:11,color:"#9ca3af",marginTop:1}}>⚙️ {inc.mechanism}</div>}
            {inc.description&&<div style={{fontSize:12,color:"#9ca3af",marginTop:3}}>{inc.description}</div>}
          </div>
        </div>
      </div>;
    })}
  </div>;
}

// ─── GLOBAL CALENDAR (coordinador) ───────────────────────────
function GlobalCalendarView({teams}){
  const [curDate,setCurDate]=useState(new Date());
  const y=curDate.getFullYear(),m=curDate.getMonth();
  const firstDay=new Date(y,m,1).getDay()||7;
  const daysInMonth=new Date(y,m+1,0).getDate();
  const todayStr=today();
  const [selDate,setSelDate]=useState(null);

  // Build all events from all teams
  const byDate={};
  const TEAM_COLORS=["#2563eb","#22c55e","#f97316","#8b5cf6","#ec4899","#06b6d4","#eab308","#ef4444"];
  teams.forEach((team,ti)=>{
    const color=TEAM_COLORS[ti%TEAM_COLORS.length];
    [...(team.sessions||[]).map(s=>({...s,type:"training",teamName:team.name,teamColor:color})),
     ...(team.matches||[]).map(s=>({...s,type:"match",teamName:team.name,teamColor:color})),
     ...(team.meetings||[]).map(s=>({...s,type:"meeting",teamName:team.name,teamColor:color}))
    ].forEach(s=>{ if(!byDate[s.date])byDate[s.date]=[]; byDate[s.date].push(s); });
  });

  const cells=[];
  for(let i=1;i<firstDay;i++) cells.push(null);
  for(let i=1;i<=daysInMonth;i++) cells.push(i);

  const selEvents=selDate?byDate[selDate]||[]:[];

  return <div>
    <div className="sec-title">🗓️ Calendario del Club</div>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14}}>
      <button className="btn btn-ghost btn-sm" onClick={()=>setCurDate(d=>{const n=new Date(d);n.setMonth(n.getMonth()-1);return n;})}>←</button>
      <span style={{fontSize:14,fontWeight:700}}>{fmtMonth(`${y}-${String(m+1).padStart(2,"0")}`)}</span>
      <button className="btn btn-ghost btn-sm" onClick={()=>setCurDate(d=>{const n=new Date(d);n.setMonth(n.getMonth()+1);return n;})}>→</button>
    </div>

    {/* Team legend */}
    <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:12}}>
      {teams.map((t,i)=><span key={t.id} style={{background:TEAM_COLORS[i%TEAM_COLORS.length]+"20",color:TEAM_COLORS[i%TEAM_COLORS.length],border:`1px solid ${TEAM_COLORS[i%TEAM_COLORS.length]}30`,borderRadius:20,padding:"2px 9px",fontSize:11,fontWeight:600}}>{t.name}</span>)}
    </div>

    <div className="cal-grid">
      {["L","M","X","J","V","S","D"].map(d=><div key={d} className="cal-day-hdr">{d}</div>)}
      {cells.map((day,i)=>{
        if(!day) return <div key={`e${i}`}/>;
        const ds=`${y}-${String(m+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`;
        const daySess=byDate[ds]||[],isToday=ds===todayStr,isSel=ds===selDate;
        return <div key={ds} className={`cal-day${isToday?" today":""}`}
          style={{cursor:"pointer",borderColor:isSel?"#2563eb":isToday?"#2563eb":"transparent",background:isSel?"#2563eb18":"#1c1f2e",minHeight:44}}
          onClick={()=>setSelDate(ds===selDate?null:ds)}>
          <div className="cal-day-num" style={{color:isSel||isToday?"#2563eb":"#9ca3af",fontWeight:isSel?"700":"400"}}>{day}</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:1}}>
            {daySess.map((s,si)=><span key={si} className="cal-dot" style={{background:s.teamColor}}/>)}
          </div>
        </div>;
      })}
    </div>

    {selDate&&<div className="card" style={{marginTop:14,borderColor:"#2563eb40"}}>
      <div style={{fontWeight:700,fontSize:14,marginBottom:10}}>
        {["Lun","Mar","Mié","Jue","Vie","Sáb","Dom"][new Date(selDate+"T12:00").getDay()===0?6:new Date(selDate+"T12:00").getDay()-1]} {selDate.slice(8)} — {fmtMonth(selDate.slice(0,7))}
      </div>
      {selEvents.length===0&&<div style={{fontSize:12,color:"#4b5563"}}>Sin eventos este día</div>}
      {selEvents.map((s,i)=><div key={i} style={{background:s.teamColor+"12",border:`1px solid ${s.teamColor}25`,borderRadius:8,padding:"8px 11px",marginBottom:6}}>
        <div style={{fontSize:12,fontWeight:600,color:s.teamColor}}>
          {s.type==="training"?"🏃":s.type==="match"?"⚽":"📅"} {s.teamName}
        </div>
        <div style={{fontSize:12,color:"#e2e4f0",marginTop:2}}>{s.topic||s.rival||s.title||""}</div>
        {s.type==="match"&&s.goalsFor!==""&&s.goalsAgainst!==""&&<div style={{fontSize:11,color:"#6b7280"}}>Resultado: {s.goalsFor}-{s.goalsAgainst}</div>}
        {s.type==="meeting"&&s.time&&<div style={{fontSize:11,color:"#6b7280"}}>{s.time} · {s.type_label||""}</div>}
        <div style={{fontSize:11,color:isComplete(s)?"#22c55e":"#f97316",marginTop:2}}>{s.type==="training"||s.type==="match"?isComplete(s)?"✓ Completo":"⏳ Pendiente":""}</div>
      </div>)}
    </div>}
  </div>;
}

// ─── INFORME PDF MENSUAL ──────────────────────────────────────
function InformeMensual({teams}){
  const [selTeam,setSelTeam]=useState(teams[0]?.id||"");
  const [selMonth,setSelMonth]=useState(today().slice(0,7));
  const team=teams.find(t=>t.id===selTeam);

  const generate=()=>{
    if(!team)return;
    const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))].filter(s=>s.date.startsWith(selMonth));
    const players=team.players||[];
    const dur=DURATION[team.category]||DURATION.default;

    let statsHtml=players.map(p=>{
      let present=0,absent=0,justified=0,injured=0,total=0,rpeSum=0,rpeCount=0,conv=0,mins=0;
      allS.forEach(s=>{const a=s.attendance?.[p.id];if(!a)return;total++;if(a.state==="present")present++;else if(a.state==="absent")absent++;else if(a.state==="justified")justified++;else if(a.state==="injured")injured++;if(s.stype==="training"&&s.rpe?.[p.id]){rpeSum+=s.rpe[p.id];rpeCount++;}if(s.stype==="match"){if(s.convocados?.includes(p.id))conv++;if(s.matchData?.[p.id]?.minutes)mins+=parseInt(s.matchData[p.id].minutes)||0;}});
      if(total===0)return"";
      const pct=Math.round(present/total*100);
      return`<tr><td>${p.name}</td><td>${p.position||"—"}</td><td>${total}</td><td style="color:${pct>=80?"#22c55e":pct>=60?"#eab308":"#ef4444"}">${pct}%</td><td>${absent}</td><td>${justified}</td><td>${conv}</td><td>${mins}'</td><td>${rpeCount?(rpeSum/rpeCount).toFixed(1):"—"}</td></tr>`;
    }).filter(Boolean).join("");

    const matches=allS.filter(s=>s.stype==="match");
    const wins=matches.filter(s=>parseInt(s.goalsFor)>parseInt(s.goalsAgainst)).length;
    const draws=matches.filter(s=>s.goalsFor!=""&&parseInt(s.goalsFor)===parseInt(s.goalsAgainst)).length;
    const losses=matches.filter(s=>parseInt(s.goalsFor)<parseInt(s.goalsAgainst)).length;

    const incidencias=allS.flatMap(s=>(s.incidencias||[]).map(inc=>({...inc,sessionDate:s.date})));
    const incHtml=incidencias.map(inc=>{const itype=INCIDENCE_TYPES.find(t=>t.id===inc.type);const player=players.find(p=>p.id===inc.playerId);return`<tr><td>${fmtDate(inc.sessionDate)}</td><td>${itype?.label||inc.type}</td><td>${inc.severity}</td><td>${player?.name||"—"}</td><td>${inc.injuryZone?`${inc.injuryZoneGroup} · ${inc.injuryZone}`:"—"}</td><td>${inc.description||"—"}</td></tr>`;}).join("");

    const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Informe ${team.name} — ${fmtMonth(selMonth)}</title><style>
      body{font-family:Arial,sans-serif;padding:32px;color:#1a1a1a;max-width:900px;margin:0 auto;}
      h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:8px;}
      h2{color:#1a3a6b;margin-top:28px;font-size:16px;}
      table{width:100%;border-collapse:collapse;margin-top:10px;font-size:13px;}
      th{background:#1a3a6b;color:white;padding:8px 10px;text-align:left;}
      td{padding:7px 10px;border-bottom:1px solid #eee;}
      tr:nth-child(even){background:#f8f9fa;}
      .stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:14px 0;}
      .stat-box{background:#f0f4ff;border-radius:8px;padding:14px;text-align:center;}
      .stat-val{font-size:24px;font-weight:700;color:#1a3a6b;}
      .stat-lbl{font-size:11px;color:#666;margin-top:3px;}
      @media print{body{padding:16px;}}
    </style></head><body>
      <h1>⚽ Informe Mensual — ${team.name}</h1>
      <p style="color:#666">${fmtMonth(selMonth)} · ${team.category} · Generado el ${fmtDate(today())}</p>
      <div class="stat-grid">
        <div class="stat-box"><div class="stat-val">${allS.filter(s=>s.stype==="training").length}</div><div class="stat-lbl">Entrenamientos</div></div>
        <div class="stat-box"><div class="stat-val">${matches.length}</div><div class="stat-lbl">Partidos</div></div>
        <div class="stat-box"><div class="stat-val">${wins}V ${draws}E ${losses}D</div><div class="stat-lbl">Resultados</div></div>
        <div class="stat-box"><div class="stat-val">${matches.reduce((a,s)=>a+(parseInt(s.goalsFor)||0),0)}</div><div class="stat-lbl">Goles a favor</div></div>
        <div class="stat-box"><div class="stat-val">${matches.reduce((a,s)=>a+(parseInt(s.goalsAgainst)||0),0)}</div><div class="stat-lbl">Goles en contra</div></div>
        <div class="stat-box"><div class="stat-val">${incidencias.length}</div><div class="stat-lbl">Incidencias</div></div>
      </div>
      <h2>📋 Asistencia y rendimiento por jugador</h2>
      <table><thead><tr><th>Jugador</th><th>Posición</th><th>Sesiones</th><th>Asistencia</th><th>Ausencias</th><th>Justificadas</th><th>Convoc.</th><th>Minutos</th><th>RPE medio</th></tr></thead><tbody>${statsHtml}</tbody></table>
      ${incHtml?`<h2>⚡ Incidencias del mes</h2><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Gravedad</th><th>Jugador</th><th>Zona</th><th>Descripción</th></tr></thead><tbody>${incHtml}</tbody></table>`:""}
      <p style="margin-top:32px;font-size:11px;color:#999">Generado por Canet F.C. App · ${fmtMonth(selMonth)}</p>
    </body></html>`;

    const blob=new Blob([html],{type:"text/html;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const win=window.open(url,"_blank");
    if(win) win.onload=()=>{ win.print(); URL.revokeObjectURL(url); };
  };

  // Get available months
  const months=new Set();
  teams.forEach(t=>[...(t.sessions||[]),...(t.matches||[])].forEach(s=>months.add(s.date.slice(0,7))));
  const monthList=[...months].sort((a,b)=>b.localeCompare(a));

  return <div>
    <div className="sec-title">📄 Informe mensual</div>
    <div className="card">
      <div className="frow">
        <div className="fg"><label className="flabel">Equipo</label>
          <select className="fselect" value={selTeam} onChange={e=>setSelTeam(e.target.value)}>
            {teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        </div>
        <div className="fg"><label className="flabel">Mes</label>
          <select className="fselect" value={selMonth} onChange={e=>setSelMonth(e.target.value)}>
            {monthList.length?monthList.map(m=><option key={m} value={m}>{fmtMonth(m)}</option>):<option value={selMonth}>{fmtMonth(selMonth)}</option>}
          </select>
        </div>
      </div>
      <button className="btn btn-primary" style={{width:"100%",justifyContent:"center",marginTop:4}} onClick={generate}>📄 Generar informe PDF</button>
      <div style={{fontSize:11,color:"#4b5563",marginTop:8}}>Se abrirá en una nueva pestaña listo para imprimir o guardar como PDF</div>
    </div>
  </div>;
}

// ─── PLANTILLAS COORDINADOR ───────────────────────────────────
function PlantillasCoordView({teams,persist}){
  const [showForm,setShowForm]=useState(false);
  const [form,setForm]=useState({name:"",sessionTypes:[],notes:""});
  const [confirm,setConfirm]=useState(null);

  // Custom templates stored in first team's parent — stored globally
  const customTemplates=teams[0]?.customTemplates||[];

  const save=()=>{
    if(!form.name.trim())return;
    const t={id:genId(),...form};
    persist(teams.map(team=>({...team,customTemplates:[...(team.customTemplates||[]),t]})));
    setForm({name:"",sessionTypes:[],notes:""});setShowForm(false);
  };

  const remove=(id)=>{
    if(confirm) persist(teams.map(team=>({...team,customTemplates:(team.customTemplates||[]).filter(t=>t.id!==id)})));
    setConfirm(null);
  };

  return <div>
    {confirm&&<Confirm msg={`¿Eliminar la plantilla "${confirm.name}"?`} onOk={()=>remove(confirm.id)} onCancel={()=>setConfirm(null)}/>}
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16}}>
      <div className="sec-title" style={{marginBottom:0}}>📝 Plantillas de sesión</div>
      <button className="btn btn-primary btn-sm" onClick={()=>setShowForm(!showForm)}>+ Nueva</button>
    </div>
    <div className="alert alert-info" style={{marginBottom:14}}>Las plantillas permiten a los entrenadores crear sesiones de un tap. Se definen aquí y aparecen en todos los equipos.</div>
    {showForm&&<div className="card">
      <div className="card-title">Nueva plantilla</div>
      <div className="fg" style={{marginBottom:9}}>
        <label className="flabel">Nombre</label>
        <input className="finput" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Ej: Trabajo de transiciones..."/>
      </div>
      <div className="fg" style={{marginBottom:9}}>
        <label className="flabel">Tipos de contenido</label>
        <TypePicker value={form.sessionTypes} onChange={v=>setForm({...form,sessionTypes:v})}/>
      </div>
      <div className="fg" style={{marginBottom:12}}>
        <label className="flabel">Descripción / Objetivo</label>
        <textarea className="ftextarea" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})} placeholder="Objetivos de la sesión, aspectos a trabajar..."/>
      </div>
      <div style={{display:"flex",gap:8}}>
        <button className="btn btn-primary btn-sm" onClick={save}>Guardar</button>
        <button className="btn btn-outline btn-sm" onClick={()=>setShowForm(false)}>Cancelar</button>
      </div>
    </div>}

    <div style={{fontSize:13,fontWeight:600,color:"#6b7280",marginBottom:10}}>Plantillas por defecto del club</div>
    {DEFAULT_TEMPLATES.map(t=>{
      const pills=(t.sessionTypes||[]).map(id=>SESSION_TYPES.find(st=>st.id===id)).filter(Boolean);
      return <div key={t.id} className="card-sm" style={{marginBottom:8}}>
        <div style={{fontWeight:600,fontSize:13,marginBottom:4}}>{t.name}</div>
        <div style={{display:"flex",gap:3,flexWrap:"wrap",marginBottom:t.notes?4:0}}>
          {pills.map(p=><span key={p.id} style={{background:p.color+"15",color:p.color,fontSize:10,fontWeight:600,padding:"1px 6px",borderRadius:20}}>{p.label}</span>)}
        </div>
        {t.notes&&<div style={{fontSize:11,color:"#6b7280"}}>{t.notes}</div>}
      </div>;
    })}

    {customTemplates.length>0&&<>
      <div style={{fontSize:13,fontWeight:600,color:"#6b7280",margin:"16px 0 10px"}}>Plantillas personalizadas ({customTemplates.length})</div>
      {customTemplates.map(t=>{
        const pills=(t.sessionTypes||[]).map(id=>SESSION_TYPES.find(st=>st.id===id)).filter(Boolean);
        return <div key={t.id} className="card-sm" style={{marginBottom:8}}>
          <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
            <div style={{flex:1}}>
              <div style={{fontWeight:600,fontSize:13,marginBottom:4}}>{t.name}</div>
              <div style={{display:"flex",gap:3,flexWrap:"wrap",marginBottom:t.notes?4:0}}>
                {pills.map(p=><span key={p.id} style={{background:p.color+"15",color:p.color,fontSize:10,fontWeight:600,padding:"1px 6px",borderRadius:20}}>{p.label}</span>)}
              </div>
              {t.notes&&<div style={{fontSize:11,color:"#6b7280"}}>{t.notes}</div>}
            </div>
            <button className="btn btn-danger btn-xs" onClick={()=>setConfirm(t)}>✕</button>
          </div>
        </div>;
      })}
    </>}
  </div>;
}

// ─── COHERENCIA METODOLÓGICA ──────────────────────────────────
function CoherenciaView({teams}){
  const thisWeek=getWeekKey(today());
  const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};

  return <div>
    <div className="sec-title">🎯 Coherencia Metodológica</div>
    <div className="alert alert-info" style={{marginBottom:14}}>Seguimiento de si los equipos trabajan los contenidos del modelo de juego del club semana a semana.</div>
    {teams.map(team=>{
      const sessions=team.sessions||[];
      const last3weeks=[0,1,2].map(i=>{
        const d=new Date(); d.setDate(d.getDate()-i*7);
        return getWeekKey(d.toISOString().slice(0,10));
      });
      const recentSessions=sessions.filter(s=>last3weeks.includes(getWeekKey(s.date)));
      const typeCount={};
      SESSION_TYPES.forEach(t=>typeCount[t.id]=0);
      recentSessions.forEach(s=>(s.sessionTypes||[]).forEach(id=>{if(typeCount[id]!==undefined)typeCount[id]++;}));
      const totalTagged=Object.values(typeCount).reduce((a,b)=>a+b,0);
      const noTactical=typeCount["tactical"]===0&&recentSessions.length>=3;
      const noGame=typeCount["game"]===0&&recentSessions.length>=3;
      const hasSessions=recentSessions.length>0;
      const thisWeekSessions=sessions.filter(s=>getWeekKey(s.date)===thisWeek);
      const hasIncomplete=thisWeekSessions.some(s=>!isComplete(s));

      return <div key={team.id} className="card" style={{marginBottom:12}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10,flexWrap:"wrap",gap:6}}>
          <div style={{fontWeight:700,fontSize:14}}>{team.name}</div>
          <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
            {!hasSessions&&<span style={{background:"#ef444420",color:"#ef4444",border:"1px solid #ef444430",borderRadius:6,padding:"2px 8px",fontSize:10,fontWeight:600}}>⚠️ Sin sesiones recientes</span>}
            {hasSessions&&hasIncomplete&&<span style={{background:"#eab30820",color:"#eab308",border:"1px solid #eab30830",borderRadius:6,padding:"2px 8px",fontSize:10,fontWeight:600}}>⏳ Sesión incompleta</span>}
            {noTactical&&<span style={{background:"#f9731620",color:"#f97316",border:"1px solid #f9731630",borderRadius:6,padding:"2px 8px",fontSize:10,fontWeight:600}}>🔴 Sin táctico 3 semanas</span>}
            {noGame&&<span style={{background:"#f9731620",color:"#f97316",border:"1px solid #f9731630",borderRadius:6,padding:"2px 8px",fontSize:10,fontWeight:600}}>🔴 Sin juego 3 semanas</span>}
            {hasSessions&&!hasIncomplete&&!noTactical&&!noGame&&<span style={{background:"#22c55e20",color:"#22c55e",border:"1px solid #22c55e30",borderRadius:6,padding:"2px 8px",fontSize:10,fontWeight:600}}>✓ OK</span>}
          </div>
        </div>
        {totalTagged>0&&<div style={{display:"flex",gap:3,flexWrap:"wrap"}}>
          {SESSION_TYPES.map(t=>{const pct=Math.round(typeCount[t.id]/totalTagged*100);if(!pct)return null;return<div key={t.id} style={{flex:"0 0 auto",background:t.color+"15",border:`1px solid ${t.color}25`,borderRadius:8,padding:"5px 9px",textAlign:"center"}}>
            <div style={{fontSize:13,fontWeight:700,color:t.color}}>{pct}%</div>
            <div style={{fontSize:10,color:"#6b7280"}}>{t.label}</div>
          </div>;})}
        </div>}
        {totalTagged===0&&hasSessions&&<div style={{fontSize:12,color:"#4b5563"}}>Sesiones sin tipo registrado</div>}
      </div>;
    })}
  </div>;
}

// ─── INFORME TRIMESTRAL ───────────────────────────────────────
function InformeTrimestral({teams}){
  const [selTeam,setSelTeam]=useState(teams[0]?.id||"");
  const [quarter,setQuarter]=useState(()=>{
    const m=new Date().getMonth()+1; // 1-12
    if(m>=8&&m<=10) return 1;
    if(m>=11||m<=1) return 2;
    if(m>=2&&m<=5) return 3;
    return 4;
  });
  const [year,setYear]=useState(new Date().getFullYear());
  const [observations,setObservations]=useState({});
  const team=teams.find(t=>t.id===selTeam);
  const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};
  const RATING_LABELS={"green":"Verde","yellow":"Amarillo","red":"Rojo"};

  const QUARTER_MONTHS = {
    1: [8,9,10],   // T1: Ago-Oct
    2: [11,12,1],  // T2: Nov-Ene
    3: [2,3,4,5],  // T3: Feb-May
    4: [6,7],      // T4: Jun-Jul
  };
  const quarterMonths=(QUARTER_MONTHS[quarter]||[]).map(m=>{
    const y = (quarter===2 && m<=1) ? year+1 : year;
    return `${y}-${String(m).padStart(2,"0")}`;
  });

  const generate=()=>{
    if(!team)return;
    const players=team.players||[];
    const playerData=players.map(p=>{
      const {trend,count,ratings}=getQuarterTrend(p.id,team.sessions,team.matches,quarterMonths);
      const byMonth={};
      quarterMonths.forEach(mk=>{
        const monthRatings=[...(team.sessions||[]).map(s=>({...s})),...(team.matches||[]).map(s=>({...s}))].filter(s=>s.date.startsWith(mk)&&s.ratings?.[p.id]).map(s=>s.ratings[p.id]);
        if(monthRatings.length) byMonth[mk]=calcTrend(monthRatings);
      });
      return{...p,trend,count,ratings,byMonth};
    }).filter(p=>p.count>0);

    const monthNames=quarterMonths.map(mk=>fmtMonth(mk).slice(0,3));

    const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Informe Trimestral T${quarter} ${year} — ${team.name}</title>
<style>
body{font-family:Arial,sans-serif;padding:32px;color:#1a1a1a;max-width:900px;margin:0 auto;}
h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:8px;font-size:20px;}
h2{color:#1a3a6b;font-size:15px;margin-top:24px;}
.player-card{border:1px solid #e0e0e0;border-radius:10px;padding:16px;margin-bottom:14px;page-break-inside:avoid;}
.player-name{font-size:16px;font-weight:700;margin-bottom:8px;}
.months{display:flex;gap:8px;margin-bottom:10px;}
.month-box{flex:1;border-radius:7px;padding:8px;text-align:center;border:1px solid #eee;}
.dot{width:16px;height:16px;border-radius:50%;display:inline-block;margin-bottom:4px;}
.green{background:#22c55e;}.yellow{background:#eab308;}.red{background:#ef4444;}.grey{background:#9ca3af;}
.trend-box{display:inline-flex;align-items:center;gap:6px;border-radius:6px;padding:4px 12px;font-weight:700;font-size:13px;}
.obs{margin-top:10px;border-top:1px solid #eee;padding-top:10px;font-size:12px;color:#555;}
.meta{font-size:12px;color:#888;margin-bottom:20px;}
@media print{body{padding:16px;}}
</style></head><body>
<h1>📊 Informe Trimestral — ${team.name}</h1>
<p class="meta">T${quarter} ${year} (${monthNames.join(" · ")}) · ${team.category} · ${playerData.length} jugadores evaluados · Generado el ${fmtDate(today())}</p>
<p style="font-size:12px;color:#666;margin-bottom:20px;background:#f0f4ff;padding:10px;border-radius:6px;">
  El color de tendencia refleja la evolución del jugador durante el trimestre, no el total acumulado. 
  Un jugador que empieza en rojo y termina en verde aparece en verde.
</p>
${playerData.map(p=>{
  const tColor=p.trend==="green"?"#22c55e":p.trend==="yellow"?"#eab308":p.trend==="red"?"#ef4444":"#9ca3af";
  const monthBoxes=quarterMonths.map((mk,i)=>{
    const c=p.byMonth[mk];
    const col=c==="green"?"#22c55e":c==="yellow"?"#eab308":c==="red"?"#ef4444":"#e0e0e0";
    return `<div class="month-box" style="border-color:${col}20;background:${col}10">
      <div class="dot" style="background:${col};margin:0 auto 4px"></div>
      <div style="font-size:11px;color:#666">${monthNames[i]}</div>
      <div style="font-size:10px;color:#999">${p.byMonth[mk]?RATING_LABELS[p.byMonth[mk]]:"Sin datos"}</div>
    </div>`;
  }).join("");
  const obs=observations[p.id]||"";
  return `<div class="player-card">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <div class="player-name">${p.name}${p.number?` · #${p.number}`:""} <span style="font-size:12px;color:#888;font-weight:400">${p.position||""}</span></div>
      <div class="trend-box" style="background:${tColor}18;color:${tColor};border:1px solid ${tColor}30">
        <div class="dot" style="background:${tColor};width:12px;height:12px"></div>
        Tendencia: ${RATING_LABELS[p.trend]||"—"}
      </div>
    </div>
    <div class="months">${monthBoxes}</div>
    <div style="font-size:11px;color:#888">${p.count} valoraciones este trimestre</div>
    ${obs?`<div class="obs"><strong>Observaciones:</strong> ${obs}</div>`:`<div class="obs" style="color:#ccc">Sin observaciones añadidas</div>`}
  </div>`;
}).join("")}
<p style="margin-top:32px;font-size:10px;color:#bbb">Canet F.C. · App de Gestión · T${quarter} ${year}</p>
</body></html>`;

    const blob=new Blob([html],{type:"text/html;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const win=window.open(url,"_blank");
    if(win) setTimeout(()=>{ win.print(); URL.revokeObjectURL(url); },500);
  };

  const players=(team?.players||[]).filter(p=>{
    const {count}=getQuarterTrend(p.id,team?.sessions,team?.matches,quarterMonths);
    return count>0;
  });

  return <div>
    <div className="sec-title">📊 Informe Trimestral</div>
    <div className="card">
      <div className="frow">
        <div className="fg"><label className="flabel">Equipo</label>
          <select className="fselect" value={selTeam} onChange={e=>setSelTeam(e.target.value)}>
            {teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        </div>
        <div className="fg" style={{maxWidth:120}}><label className="flabel">Trimestre</label>
          <select className="fselect" value={quarter} onChange={e=>setQuarter(Number(e.target.value))}>
            <option value={1}>T1 (Ago-Oct)</option>
            <option value={2}>T2 (Nov-Ene)</option>
            <option value={3}>T3 (Feb-May)</option>
            <option value={4}>T4 (Jun-Jul)</option>
          </select>
        </div>
        <div className="fg" style={{maxWidth:90}}><label className="flabel">Año</label>
          <select className="fselect" value={year} onChange={e=>setYear(Number(e.target.value))}>
            {[2024,2025,2026,2027].map(y=><option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      </div>
      <div style={{fontSize:12,color:"#6b7280",marginBottom:10}}>
        T{quarter} · {quarterMonths.map(m=>fmtMonth(m).slice(0,3)).join(" · ")} · {players.length} jugadores con datos
      </div>
    </div>

    {players.length===0&&<div className="empty"><div className="empty-icon">📊</div>Sin valoraciones en este trimestre</div>}

    {players.length>0&&(()=>{
      const withTrend=players.map(p=>{const {trend}=getQuarterTrend(p.id,team.sessions,team.matches,quarterMonths);return{...p,trend};});
      const greens=withTrend.filter(p=>p.trend==="green").length;
      const yellows=withTrend.filter(p=>p.trend==="yellow").length;
      const reds=withTrend.filter(p=>p.trend==="red").length;
      return <div className="card" style={{marginBottom:12}}>
        <div className="card-title">Vista rápida del equipo</div>
        <div style={{display:"flex",gap:8}}>
          {[{c:"#22c55e",n:greens,l:"Tendencia verde"},{c:"#eab308",n:yellows,l:"Tendencia amarilla"},{c:"#ef4444",n:reds,l:"Tendencia roja"}].map((s,i)=><div key={i} style={{flex:1,background:`${s.c}18`,border:`1px solid ${s.c}30`,borderRadius:9,padding:"10px 8px",textAlign:"center"}}>
            <div style={{fontSize:22,fontWeight:700,color:s.c,fontFamily:"DM Mono"}}>{s.n}</div>
            <div style={{fontSize:10,color:"#6b7280"}}>{s.l}</div>
          </div>)}
        </div>
        {reds>0&&<div style={{marginTop:8,fontSize:12,color:"#fca5a5"}}>⚠️ {withTrend.filter(p=>p.trend==="red").map(p=>p.name.split(" ")[0]).join(", ")} — requieren atención</div>}
      </div>;
    })()}

    {players.map(p=>{
      const {trend,count}=getQuarterTrend(p.id,team.sessions,team.matches,quarterMonths);
      const byMonth={};
      quarterMonths.forEach(mk=>{
        const mr=[...(team.sessions||[]),...(team.matches||[])].filter(s=>s.date.startsWith(mk)&&s.ratings?.[p.id]).map(s=>s.ratings[p.id]);
        if(mr.length)byMonth[mk]=calcTrend(mr);
      });
      const tColor=RATING_COLORS[trend]||"#6b7280";
      return <div key={p.id} className="card" style={{marginBottom:10}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10,flexWrap:"wrap",gap:6}}>
          <div><div style={{fontWeight:700,fontSize:14}}>{p.name}{p.number?` · #${p.number}`:""}</div><div style={{fontSize:11,color:"#6b7280"}}>{p.position||"—"} · {count} valoraciones</div></div>
          <div style={{display:"flex",alignItems:"center",gap:6,background:`${tColor}18`,border:`1px solid ${tColor}30`,borderRadius:8,padding:"5px 10px"}}>
            <div style={{width:12,height:12,borderRadius:"50%",background:tColor}}/>
            <span style={{fontSize:12,fontWeight:700,color:tColor}}>Tendencia</span>
          </div>
        </div>
        <div style={{display:"flex",gap:6,marginBottom:10}}>
          {quarterMonths.map((mk,i)=>{
            const c=byMonth[mk];
            const col=c?RATING_COLORS[c]:"#252836";
            return <div key={mk} style={{flex:1,background:`${col}18`,border:`1px solid ${col}30`,borderRadius:8,padding:"8px 6px",textAlign:"center"}}>
              <div style={{width:12,height:12,borderRadius:"50%",background:col,margin:"0 auto 4px"}}/>
              <div style={{fontSize:10,color:"#6b7280"}}>{fmtMonth(mk).slice(0,3)}</div>
            </div>;
          })}
        </div>
        <div className="fg">
          <label className="flabel">Observaciones</label>
          <textarea className="ftextarea" style={{minHeight:52}} value={observations[p.id]||""} onChange={e=>setObservations({...observations,[p.id]:e.target.value})} placeholder="Aspectos destacados del trimestre, puntos de mejora..."/>
        </div>
        <button className="btn btn-ghost btn-sm" style={{marginTop:8,width:"100%",justifyContent:"center"}} onClick={()=>{
          const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};
          const RATING_LABELS={"green":"Verde","yellow":"Amarillo","red":"Rojo"};
          const tColor=RATING_COLORS[trend]||"#9ca3af";
          const monthBoxes=quarterMonths.map((mk,i)=>{
            const c=byMonth[mk];
            const col=RATING_COLORS[c]||"#e0e0e0";
            return `<div style="flex:1;background:${col}10;border:1px solid ${col}30;border-radius:7px;padding:8px;text-align:center"><div style="width:12px;height:12px;border-radius:50%;background:${col};margin:0 auto 4px"></div><div style="font-size:11px;color:#666">${fmtMonth(mk).slice(0,3)}</div><div style="font-size:10px;color:#999">${c?RATING_LABELS[c]:"Sin datos"}</div></div>`;
          }).join("");
          const obs=observations[p.id]||"";
          const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
          <title>Informe T${quarter} — ${p.name}</title>
          <style>body{font-family:Arial,sans-serif;padding:32px;color:#1a1a1a;max-width:700px;margin:0 auto;}h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:8px;font-size:18px;}.months{display:flex;gap:8px;margin:14px 0;}.trend{display:inline-flex;align-items:center;gap:8px;border-radius:8px;padding:8px 16px;font-weight:700;font-size:14px;margin:10px 0;}.dot{width:14px;height:14px;border-radius:50%;display:inline-block;}.obs{background:#f8f9fa;border-radius:8px;padding:14px;margin-top:14px;font-size:13px;line-height:1.6;}@media print{body{padding:16px;}}</style>
          </head><body>
          <h1>📊 Informe Trimestral T${quarter} ${year}</h1>
          <p style="color:#888;font-size:12px">${team?.name||""} · ${team?.category||""} · ${p.position||"—"}${p.number?` · #${p.number}`:""}</p>
          <p style="color:#888;font-size:12px;margin-bottom:20px">Generado el ${fmtDate(today())} · ${count} valoraciones</p>
          <div class="trend" style="background:${tColor}15;color:${tColor};border:1px solid ${tColor}30">
            <div class="dot" style="background:${tColor}"></div>
            Tendencia del trimestre: ${RATING_LABELS[trend]||"Sin datos"}
          </div>
          <div style="font-size:12px;color:#666;margin-bottom:8px">El color refleja la evolución durante el trimestre, no el total acumulado.</div>
          <div class="months">${monthBoxes}</div>
          ${obs?`<div class="obs"><strong>Observaciones del entrenador:</strong><br>${obs}</div>`:`<div class="obs" style="color:#ccc">Sin observaciones añadidas este trimestre.</div>`}
          <p style="font-size:10px;color:#bbb;margin-top:32px">Canet F.C. · T${quarter} ${year} · ${fmtDate(today())}</p>
          </body></html>`;
          const blob=new Blob([html],{type:"text/html;charset=utf-8"});
          const url=URL.createObjectURL(blob);
          const win=window.open(url,"_blank");
          if(win) setTimeout(()=>{ win.print(); URL.revokeObjectURL(url); },500);
        }}>📄 Informe individual PDF</button>
      </div>;
    })}

    {players.length>0&&<button className="btn btn-primary" style={{width:"100%",justifyContent:"center",marginTop:8}} onClick={generate}>📄 Informe completo del equipo PDF</button>}
  </div>;
}

// ─── FICHA DE TRASPASO ────────────────────────────────────────
function FichaTraspasoView({teams,persist}){
  const [selTeam,setSelTeam]=useState(teams[0]?.id||"");
  const [selPlayer,setSelPlayer]=useState("");
  const [destTeam,setDestTeam]=useState("");
  const team=teams.find(t=>t.id===selTeam);
  const player=team?.players?.find(p=>p.id===selPlayer);
  const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};

  const generatePDF=()=>{
    if(!player||!team)return;
    const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))];
    let present=0,absent=0,justified=0,injured=0,total=0,conv=0,mins=0,starters=0;
    allS.forEach(s=>{const a=s.attendance?.[player.id];if(!a)return;total++;if(a.state==="present")present++;else if(a.state==="absent")absent++;else if(a.state==="justified")justified++;else if(a.state==="injured")injured++;if(s.stype==="match"){if(s.convocados?.includes(player.id))conv++;if(s.matchData?.[player.id]?.starter)starters++;if(s.matchData?.[player.id]?.minutes)mins+=parseInt(s.matchData[player.id].minutes)||0;}});
    const byMonth=getMonthRatings(player.id,team.sessions,team.matches);
    const months=Object.keys(byMonth).sort();
    const overallTrend=calcTrend(months.flatMap(m=>byMonth[m]));
    const tColor=RATING_COLORS[overallTrend]||"#9ca3af";
    const incidencias=allS.flatMap(s=>(s.incidencias||[]).filter(i=>i.playerId===player.id));
    const injuries=[];const seen=new Set();
    allS.forEach(s=>Object.entries(s.attendance||{}).forEach(([pid,a])=>{if(pid!==player.id||a.state!=="injured")return;const k=`${a.injuryStart||s.date}_${a.injuryType}`;if(!seen.has(k)){seen.add(k);injuries.push({type:a.injuryType,start:a.injuryStart||s.date,end:a.injuryEnd});}}));

    const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Ficha Traspaso — ${player.name}</title>
<style>
body{font-family:Arial,sans-serif;padding:32px;color:#1a1a1a;max-width:800px;margin:0 auto;}
h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:8px;}
h2{color:#1a3a6b;font-size:15px;margin-top:20px;border-bottom:1px solid #eee;padding-bottom:4px;}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:12px 0;}
.box{background:#f8f9fa;border-radius:8px;padding:12px;text-align:center;}
.val{font-size:22px;font-weight:700;color:#1a3a6b;}.lbl{font-size:11px;color:#888;}
.dot{width:14px;height:14px;border-radius:50%;display:inline-block;}
table{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px;}
th{background:#1a3a6b;color:white;padding:6px 8px;text-align:left;}
td{padding:6px 8px;border-bottom:1px solid #eee;}
@media print{body{padding:16px;}}
</style></head><body>
<h1>🔄 Ficha de Traspaso — ${player.name}</h1>
<p style="color:#888;font-size:12px">Equipo origen: ${team.name} · ${team.category} · Generado el ${fmtDate(today())}</p>
<h2>Datos del jugador</h2>
<div class="grid">
  <div class="box"><div class="val">${player.number||"—"}</div><div class="lbl">Dorsal</div></div>
  <div class="box"><div class="val" style="font-size:14px">${player.position||"—"}</div><div class="lbl">Posición</div></div>
  <div class="box"><div class="val" style="font-size:14px">${player.dob?fmtDate(player.dob):"—"}</div><div class="lbl">Fecha nac.</div></div>
</div>
${player.emergencyName||player.emergencyPhone?`<p style="font-size:12px;color:#666">Contacto emergencia: ${player.emergencyName||""} ${player.emergencyPhone?`· ${player.emergencyPhone}`:""}</p>`:""}
${player.mutua?`<p style="font-size:12px;color:#666">Mutua: ${player.mutua}</p>`:""}
${player.allergies?`<p style="font-size:12px;color:#ef4444;font-weight:600">⚠️ Alergias: ${player.allergies}</p>`:""}
<h2>Asistencia y participación</h2>
<div class="grid">
  <div class="box"><div class="val">${total?Math.round(present/total*100):0}%</div><div class="lbl">Asistencia (${present}/${total})</div></div>
  <div class="box"><div class="val">${conv}</div><div class="lbl">Convocatorias</div></div>
  <div class="box"><div class="val">${starters}</div><div class="lbl">Titularidades</div></div>
  <div class="box"><div class="val">${mins}'</div><div class="lbl">Minutos jugados</div></div>
  <div class="box"><div class="val">${injuries.length}</div><div class="lbl">Lesiones</div></div>
  <div class="box"><div class="val" style="display:flex;align-items:center;justify-content:center;gap:6px"><span class="dot" style="background:${tColor}"></span>${["green","yellow","red"].includes(overallTrend)?["Verde","Amarillo","Rojo"][["green","yellow","red"].indexOf(overallTrend)]:"—"}</div><div class="lbl">Tendencia global</div></div>
</div>
${months.length>1?`<h2>Evolución mes a mes</h2><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">${months.map(mk=>{const c=calcTrend(byMonth[mk]);const col=RATING_COLORS[c]||"#9ca3af";return`<div style="background:${col}15;border:1px solid ${col}30;border-radius:7px;padding:8px 12px;text-align:center"><div class="dot" style="background:${col};margin:0 auto 4px"></div><div style="font-size:11px;color:#666">${fmtMonth(mk).slice(0,3)}</div></div>`;}).join("")}</div>`:""}
${injuries.length?`<h2>Historial lesiones</h2><table><thead><tr><th>Tipo</th><th>Inicio</th><th>Alta</th></tr></thead><tbody>${injuries.map(i=>`<tr><td>${i.type||"Sin especificar"}</td><td>${fmtDate(i.start)}</td><td>${i.end?fmtDate(i.end):"En curso"}</td></tr>`).join("")}</tbody></table>`:""}
${incidencias.length?`<h2>Incidencias relevantes</h2><table><thead><tr><th>Tipo</th><th>Gravedad</th><th>Fecha</th><th>Descripción</th></tr></thead><tbody>${incidencias.filter(i=>i.severity!=="Leve").map(i=>{const itype=INCIDENCE_TYPES.find(t=>t.id===i.type);return`<tr><td>${itype?.label||i.type}</td><td>${i.severity}</td><td>${fmtDate(i.date)}</td><td>${i.description||"—"}</td></tr>`;}).join("")}</tbody></table>`:""}
<p style="margin-top:32px;font-size:10px;color:#bbb">Canet F.C. · Ficha de Traspaso · ${fmtDate(today())}</p>
</body></html>`;

    const blob=new Blob([html],{type:"text/html;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const win=window.open(url,"_blank");
    if(win) setTimeout(()=>{ win.print(); URL.revokeObjectURL(url); },500);
  };

  const doTransfer=()=>{
    if(!player||!destTeam||destTeam===selTeam)return;
    const dest=teams.find(t=>t.id===destTeam);
    if(!dest)return;
    persist(teams.map(t=>{
      if(t.id===selTeam) return{...t,players:t.players.filter(p=>p.id!==player.id)};
      if(t.id===destTeam) return{...t,players:[...t.players,{...player,transferredFrom:team.name,transferDate:today()}]};
      return t;
    }));
    setSelPlayer("");setDestTeam("");
  };

  return <div>
    <div className="sec-title">🔄 Ficha de Traspaso</div>
    <div className="card">
      <div className="frow">
        <div className="fg"><label className="flabel">Equipo origen</label>
          <select className="fselect" value={selTeam} onChange={e=>{setSelTeam(e.target.value);setSelPlayer("");}}>
            {teams.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        </div>
        <div className="fg"><label className="flabel">Jugador</label>
          <select className="fselect" value={selPlayer} onChange={e=>setSelPlayer(e.target.value)}>
            <option value="">Seleccionar...</option>
            {(team?.players||[]).map(p=><option key={p.id} value={p.id}>{p.number?`#${p.number} `:""}{p.name}</option>)}
          </select>
        </div>
      </div>
      {selPlayer&&<>
        <button className="btn btn-primary btn-sm" style={{marginBottom:10}} onClick={generatePDF}>📄 Generar ficha PDF</button>
        <div className="divider"/>
        <div style={{fontSize:13,fontWeight:600,marginBottom:8}}>Traspasar a otro equipo</div>
        <div className="frow">
          <div className="fg"><label className="flabel">Equipo destino</label>
            <select className="fselect" value={destTeam} onChange={e=>setDestTeam(e.target.value)}>
              <option value="">Seleccionar...</option>
              {teams.filter(t=>t.id!==selTeam).map(t=><option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
        </div>
        {destTeam&&<button className="btn btn-danger btn-sm" onClick={doTransfer}>🔄 Ejecutar traspaso</button>}
        <div style={{fontSize:11,color:"#4b5563",marginTop:6}}>El traspaso mueve al jugador al equipo destino manteniendo todos sus datos históricos</div>
      </>}
    </div>
  </div>;
}

// ─── CHECKLIST OBJETIVOS SESIÓN ───────────────────────────────
function ChecklistObjetivos({session,updateTeam,team}){
  const [showAdd,setShowAdd]=useState(false);
  const [newObj,setNewObj]=useState("");
  const checklist=session.checklist||[];

  const add=()=>{
    if(!newObj.trim())return;
    const item={id:genId(),text:newObj.trim(),done:false};
    updateTeam(team.id,t=>({...t,sessions:t.sessions.map(s=>s.id===session.id?{...s,checklist:[...(s.checklist||[]),item]}:s)}));
    setNewObj("");setShowAdd(false);
  };
  const toggle=id=>updateTeam(team.id,t=>({...t,sessions:t.sessions.map(s=>s.id===session.id?{...s,checklist:(s.checklist||[]).map(i=>i.id===id?{...i,done:!i.done}:i)}:s)}));
  const remove=id=>updateTeam(team.id,t=>({...t,sessions:t.sessions.map(s=>s.id===session.id?{...s,checklist:(s.checklist||[]).filter(i=>i.id!==id)}:s)}));

  const done=checklist.filter(i=>i.done).length;

  return <div style={{marginTop:8,borderTop:"1px solid #252836",paddingTop:8}}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:7}}>
      <div style={{fontSize:11,fontWeight:600,color:"#9ca3af",textTransform:"uppercase",letterSpacing:".5px"}}>
        Objetivos de la sesión {checklist.length>0&&<span style={{color:done===checklist.length?"#22c55e":"#eab308"}}>({done}/{checklist.length})</span>}
      </div>
      <button className="btn btn-xs" style={{background:"#2563eb15",color:"#93c5fd",border:"1px solid #2563eb25"}} onClick={()=>setShowAdd(!showAdd)}>+ Objetivo</button>
    </div>
    {checklist.map(item=><div key={item.id} style={{display:"flex",alignItems:"center",gap:8,padding:"5px 0",borderBottom:"1px solid #1a1d2a"}}>
      <div onClick={()=>toggle(item.id)} style={{width:18,height:18,borderRadius:5,border:`2px solid ${item.done?"#22c55e":"#252836"}`,background:item.done?"#22c55e":"transparent",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"white",flexShrink:0}}>{item.done?"✓":""}</div>
      <span style={{flex:1,fontSize:12,color:item.done?"#6b7280":"#e2e4f0",textDecoration:item.done?"line-through":"none"}}>{item.text}</span>
      <button className="btn btn-danger btn-xs" onClick={()=>remove(item.id)}>✕</button>
    </div>)}
    {showAdd&&<div style={{display:"flex",gap:6,marginTop:7}}>
      <input className="finput" style={{fontSize:12}} value={newObj} onChange={e=>setNewObj(e.target.value)} placeholder="Ej: Trabajo de pressing alto..." onKeyDown={e=>e.key==="Enter"&&add()} autoFocus/>
      <button className="btn btn-primary btn-sm" onClick={add}>+</button>
    </div>}
    {checklist.length===0&&!showAdd&&<div style={{fontSize:11,color:"#4b5563",padding:"4px 0"}}>Sin objetivos definidos para esta sesión</div>}
  </div>;
}

// ─── RESUMEN SEMANAL COORDINADOR ──────────────────────────────
function ResumenSemanalView({teams}){
  const [selWeek,setSelWeek]=useState(getWeekKey(today()));
  const weeks=new Set();
  teams.forEach(t=>[...(t.sessions||[]),...(t.matches||[])].forEach(s=>weeks.add(getWeekKey(s.date))));
  const weekList=[...weeks].sort((a,b)=>b.localeCompare(a)).slice(0,12);
  if(!weekList.includes(selWeek)&&weekList.length){}

  const weekData=teams.map(team=>{
    const wkS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))].filter(s=>getWeekKey(s.date)===selWeek);
    const incidencias=wkS.flatMap(s=>(s.incidencias||[]).map(i=>({...i,sessionDate:s.date})));
    const graves=incidencias.filter(i=>i.severity==="Grave");
    const incomplete=wkS.filter(s=>!isComplete(s));
    let tp=0,tr=0;
    wkS.forEach(s=>Object.values(s.attendance||{}).forEach(a=>{tr++;if(a.state==="present")tp++;}));
    return{team,wkS,incidencias,graves,incomplete,presencePct:tr?Math.round(tp/tr*100):null};
  });

  const totalGraves=weekData.reduce((a,d)=>a+d.graves.length,0);
  const teamsNoSessions=weekData.filter(d=>d.wkS.length===0);
  const teamsIncomplete=weekData.filter(d=>d.incomplete.length>0&&d.wkS.length>0);

  return <div>
    <div className="sec-title">📋 Resumen Semanal</div>
    <div style={{marginBottom:14}}>
      <label className="flabel" style={{display:"block",marginBottom:5}}>Semana</label>
      <select className="fselect" value={selWeek} onChange={e=>setSelWeek(e.target.value)}>
        <option value={getWeekKey(today())}>{fmtWeek(getWeekKey(today()))} (Esta semana)</option>
        {weekList.filter(w=>w!==getWeekKey(today())).map(w=><option key={w} value={w}>{fmtWeek(w)}</option>)}
      </select>
    </div>

    {/* Alertas globales */}
    {totalGraves>0&&<div className="alert alert-warn" style={{marginBottom:10}}>🔴 {totalGraves} incidencia{totalGraves>1?"s":""} grave{totalGraves>1?"s":""} esta semana</div>}
    {teamsNoSessions.length>0&&<div className="alert alert-orange" style={{marginBottom:10}}>⚠️ Sin sesiones: {teamsNoSessions.map(d=>d.team.name).join(", ")}</div>}
    {teamsIncomplete.length>0&&<div className="alert" style={{background:"#eab30812",border:"1px solid #eab30825",color:"#fde68a",marginBottom:10}}>⏳ Sesiones incompletas: {teamsIncomplete.map(d=>d.team.name).join(", ")}</div>}
    {totalGraves===0&&teamsNoSessions.length===0&&teamsIncomplete.length===0&&<div className="alert alert-info" style={{marginBottom:10}}>✅ Todo en orden esta semana</div>}

    {/* Por equipo */}
    {weekData.map(({team,wkS,incidencias,graves,incomplete,presencePct})=><div key={team.id} className="card" style={{marginBottom:10}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8,flexWrap:"wrap",gap:5}}>
        <div>
          <div style={{fontWeight:700,fontSize:13}}>{team.name}</div>
          <div style={{fontSize:11,color:"#6b7280"}}>{team.category} · {team.format||"F11"}</div>
        </div>
        <div style={{display:"flex",gap:5,flexWrap:"wrap"}}>
          {wkS.length===0&&<span style={{background:"#ef444420",color:"#ef4444",border:"1px solid #ef444430",borderRadius:6,padding:"2px 7px",fontSize:10,fontWeight:600}}>Sin sesiones</span>}
          {incomplete.length>0&&<span style={{background:"#eab30820",color:"#eab308",border:"1px solid #eab30830",borderRadius:6,padding:"2px 7px",fontSize:10,fontWeight:600}}>⏳ {incomplete.length} incompleta{incomplete.length>1?"s":""}</span>}
          {graves.length>0&&<span style={{background:"#ef444420",color:"#ef4444",border:"1px solid #ef444430",borderRadius:6,padding:"2px 7px",fontSize:10,fontWeight:600}}>🔴 {graves.length} grave{graves.length>1?"s":""}</span>}
          {wkS.length>0&&incomplete.length===0&&graves.length===0&&<span style={{background:"#22c55e20",color:"#22c55e",border:"1px solid #22c55e30",borderRadius:6,padding:"2px 7px",fontSize:10,fontWeight:600}}>✓ OK</span>}
        </div>
      </div>
      {wkS.length>0&&<div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
        <div className="stat-box" style={{flex:1,padding:8,minWidth:70}}><div className="stat-val" style={{fontSize:16}}>{wkS.filter(s=>s.stype==="training").length}</div><div className="stat-lbl">Entrenos</div></div>
        <div className="stat-box" style={{flex:1,padding:8,minWidth:70}}><div className="stat-val" style={{fontSize:16}}>{wkS.filter(s=>s.stype==="match").length}</div><div className="stat-lbl">Partidos</div></div>
        <div className="stat-box" style={{flex:1,padding:8,minWidth:70}}><div className="stat-val" style={{fontSize:16,color:presencePct>=75?"#22c55e":presencePct>=50?"#eab308":"#ef4444"}}>{presencePct!==null?`${presencePct}%`:"—"}</div><div className="stat-lbl">Asistencia</div></div>
        <div className="stat-box" style={{flex:1,padding:8,minWidth:70}}><div className="stat-val" style={{fontSize:16,color:incidencias.length>0?"#f97316":"#22c55e"}}>{incidencias.length}</div><div className="stat-lbl">Incidencias</div></div>
      </div>}
      {wkS.map(s=><div key={s.id} style={{marginTop:6,background:"#1c1f2e",borderRadius:8,padding:"7px 10px",fontSize:12}}>
        <span style={{color:s.stype==="training"?"#2563eb":"#22c55e",fontWeight:600}}>{s.stype==="training"?"🏃":"⚽"} {fmtDate(s.date)}</span>
        <span style={{color:"#6b7280",marginLeft:8}}>{s.topic||s.rival||"Sin título"}</span>
        {!isComplete(s)&&<span style={{color:"#f97316",marginLeft:8,fontSize:11}}>⏳ Sin completar</span>}
        {(s.incidencias||[]).length>0&&<span style={{color:"#ef4444",marginLeft:8,fontSize:11}}>⚡ {s.incidencias.length} incid.</span>}
      </div>)}
    </div>)}
  </div>;
}

// ─── EXPORTAR FICHAS EQUIPO ───────────────────────────────────
function ExportarFichasEquipo({teams}){
  const [selTeam,setSelTeam]=useState(teams[0]?.id||"");
  const team=teams.find(t=>t.id===selTeam);
  const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};
  const RATING_LABELS={"green":"Verde","yellow":"Amarillo","red":"Rojo"};

  const [generating,setGenerating]=useState(false);

  const generateOne=(p)=>{
    const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))];
    const RATING_COLORS={"green":"#22c55e","yellow":"#eab308","red":"#ef4444"};
    const RATING_LABELS={"green":"Verde","yellow":"Amarillo","red":"Rojo"};
    let present=0,absent=0,total=0,conv=0,mins=0,starters=0;
    allS.forEach(s=>{const a=s.attendance?.[p.id];if(!a)return;total++;if(a.state==="present")present++;else if(a.state==="absent")absent++;if(s.stype==="match"){if(s.convocados?.includes(p.id))conv++;if(s.matchData?.[p.id]?.starter)starters++;if(s.matchData?.[p.id]?.minutes)mins+=parseInt(s.matchData[p.id].minutes)||0;}});
    const byMonth=getMonthRatings(p.id,team.sessions,team.matches);
    const months=Object.keys(byMonth).sort();
    const overallTrend=calcTrend(months.flatMap(m=>byMonth[m]));
    const tColor=RATING_COLORS[overallTrend]||"#9ca3af";
    const incidencias=allS.flatMap(s=>(s.incidencias||[]).filter(i=>i.playerId===p.id));
    const injuries=[];const seen=new Set();
    allS.forEach(s=>Object.entries(s.attendance||{}).forEach(([pid,a])=>{if(pid!==p.id||a.state!=="injured")return;const k=`${a.injuryStart||s.date}`;if(!seen.has(k)){seen.add(k);injuries.push({type:a.injuryType,start:a.injuryStart||s.date,end:a.injuryEnd});}}));
    const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Ficha ${p.name}</title>
    <style>body{font-family:Arial,sans-serif;padding:28px;color:#1a1a1a;max-width:700px;margin:0 auto;}h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:6px;font-size:18px;}h2{color:#1a3a6b;font-size:14px;margin-top:16px;}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0;}.box{background:#f8f9fa;border-radius:7px;padding:10px;text-align:center;}.val{font-size:20px;font-weight:700;color:#1a3a6b;}.lbl{font-size:10px;color:#888;}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:6px;}th{background:#1a3a6b;color:white;padding:5px 7px;text-align:left;}td{padding:5px 7px;border-bottom:1px solid #eee;}@media print{body{padding:12px;}}</style>
    </head><body>
    <h1>📋 Ficha — ${p.name}</h1>
    <p style="color:#888;font-size:11px">${team.name} · ${team.category} · ${p.position||"—"}${p.number?` · #${p.number}`:""} · ${fmtDate(today())}</p>
    ${p.dob?`<p style="font-size:11px;color:#666">Fecha nac.: ${fmtDate(p.dob)}</p>`:""}
    ${p.state&&p.state!=="Disponible"?`<p style="font-size:12px;color:#ef4444;font-weight:600">Estado: ${p.state}</p>`:""}
    <h2>Estadísticas</h2>
    <div class="grid">
      <div class="box"><div class="val">${total?Math.round(present/total*100):0}%</div><div class="lbl">Asistencia (${present}/${total})</div></div>
      <div class="box"><div class="val">${conv}</div><div class="lbl">Convocatorias</div></div>
      <div class="box"><div class="val">${starters}</div><div class="lbl">Titularidades</div></div>
      <div class="box"><div class="val">${mins}'</div><div class="lbl">Minutos</div></div>
      <div class="box"><div class="val">${injuries.length}</div><div class="lbl">Lesiones</div></div>
      <div class="box" style="background:${tColor}15;border:1px solid ${tColor}25"><div class="val" style="color:${tColor};font-size:14px">${["green","yellow","red"].includes(overallTrend)?["Verde","Amarillo","Rojo"][["green","yellow","red"].indexOf(overallTrend)]:"—"}</div><div class="lbl">Tendencia</div></div>
    </div>
    ${months.length>1?`<h2>Evolución</h2><div style="display:flex;gap:6px;flex-wrap:wrap">${months.map(mk=>{const c=calcTrend(byMonth[mk]);const col=RATING_COLORS[c]||"#e0e0e0";return`<div style="flex:1;min-width:50px;background:${col}12;border:1px solid ${col}25;border-radius:6px;padding:7px;text-align:center"><div style="width:10px;height:10px;border-radius:50%;background:${col};margin:0 auto 3px"></div><div style="font-size:10px;color:#888">${fmtMonth(mk).slice(0,3)}</div></div>`;}).join("")}</div>`:""}
    ${p.emergencyName||p.emergencyPhone?`<h2>Contacto emergencia</h2><p style="font-size:12px">${p.emergencyName||""} ${p.emergencyPhone?`· <a href="tel:${p.emergencyPhone}">${p.emergencyPhone}</a>`:""}</p>`:""}
    ${p.allergies?`<p style="font-size:12px;color:#ef4444;font-weight:600">⚠️ Alergias: ${p.allergies}</p>`:""}
    ${p.mutua?`<p style="font-size:12px;color:#666">Mutua: ${p.mutua}</p>`:""}
    ${injuries.length?`<h2>Lesiones</h2><table><thead><tr><th>Tipo</th><th>Inicio</th><th>Alta</th></tr></thead><tbody>${injuries.map(i=>`<tr><td>${i.type||"—"}</td><td>${fmtDate(i.start)}</td><td>${i.end?fmtDate(i.end):"En curso"}</td></tr>`).join("")}</tbody></table>`:""}
    <p style="font-size:10px;color:#bbb;margin-top:24px">Canet F.C. · ${fmtDate(today())}</p>
    </body></html>`;
    const blob=new Blob([html],{type:"text/html;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const win=window.open(url,"_blank");
    if(win) setTimeout(()=>{ win.print(); URL.revokeObjectURL(url); },500);
  };

  const generate=()=>{
    if(!team)return;
    const players=team.players||[];
    const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))];

    const playerCards=players.map(p=>{
      let present=0,absent=0,total=0,conv=0,mins=0,starters=0;
      allS.forEach(s=>{const a=s.attendance?.[p.id];if(!a)return;total++;if(a.state==="present")present++;else if(a.state==="absent")absent++;if(s.stype==="match"){if(s.convocados?.includes(p.id))conv++;if(s.matchData?.[p.id]?.starter)starters++;if(s.matchData?.[p.id]?.minutes)mins+=parseInt(s.matchData[p.id].minutes)||0;}});
      const byMonth=getMonthRatings(p.id,team.sessions,team.matches);
      const months=Object.keys(byMonth).sort();
      const overallTrend=calcTrend(months.flatMap(m=>byMonth[m]));
      const tColor=RATING_COLORS[overallTrend]||"#9ca3af";
      const incidencias=allS.flatMap(s=>(s.incidencias||[]).filter(i=>i.playerId===p.id));
      return`<div style="border:1px solid #e0e0e0;border-radius:10px;padding:16px;margin-bottom:16px;page-break-inside:avoid">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">
          <div>
            <div style="font-size:17px;font-weight:700">${p.name}${p.number?` · #${p.number}`:""}</div>
            <div style="font-size:12px;color:#888">${p.position||"—"} · ${p.dob?fmtDate(p.dob):"Sin fecha"}</div>
            ${p.state&&p.state!=="Disponible"?`<div style="font-size:11px;color:#ef4444;font-weight:600;margin-top:2px">${p.state}</div>`:""}
          </div>
          ${overallTrend?`<div style="background:${tColor}18;border:1px solid ${tColor}30;border-radius:7px;padding:6px 12px;text-align:center"><div style="width:14px;height:14px;border-radius:50%;background:${tColor};margin:0 auto 3px"></div><div style="font-size:10px;color:${tColor};font-weight:700">${RATING_LABELS[overallTrend]||""}</div></div>`:""}
        </div>
        <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:10px">
          <div style="background:#f8f9fa;border-radius:6px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:700;color:#1a3a6b">${total?Math.round(present/total*100):0}%</div><div style="font-size:10px;color:#888">Asistencia</div></div>
          <div style="background:#f8f9fa;border-radius:6px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:700;color:#1a3a6b">${conv}</div><div style="font-size:10px;color:#888">Convoc.</div></div>
          <div style="background:#f8f9fa;border-radius:6px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:700;color:#1a3a6b">${starters}</div><div style="font-size:10px;color:#888">Titulares</div></div>
          <div style="background:#f8f9fa;border-radius:6px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:700;color:#1a3a6b">${mins}'</div><div style="font-size:10px;color:#888">Minutos</div></div>
        </div>
        ${months.length>1?`<div style="display:flex;gap:5px;margin-bottom:8px">${months.map(mk=>{const c=calcTrend(byMonth[mk]);const col=RATING_COLORS[c]||"#e0e0e0";return`<div style="flex:1;background:${col}15;border:1px solid ${col}30;border-radius:6px;padding:5px;text-align:center"><div style="width:10px;height:10px;border-radius:50%;background:${col};margin:0 auto 2px"></div><div style="font-size:9px;color:#888">${fmtMonth(mk).slice(0,3)}</div></div>`;}).join("")}</div>`:""}
        ${p.emergencyName?`<div style="font-size:11px;color:#666;margin-top:4px">📞 ${p.emergencyName}${p.emergencyPhone?` · ${p.emergencyPhone}`:""}</div>`:""}
        ${p.allergies?`<div style="font-size:11px;color:#ef4444;margin-top:2px">⚠️ Alergias: ${p.allergies}</div>`:""}
        ${incidencias.filter(i=>i.severity==="Grave").length>0?`<div style="font-size:11px;color:#ef4444;margin-top:4px">🔴 ${incidencias.filter(i=>i.severity==="Grave").length} incidencia(s) grave(s)</div>`:""}
      </div>`;
    }).join("");

    const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Fichas ${team.name}</title>
    <style>body{font-family:Arial,sans-serif;padding:24px;color:#1a1a1a;max-width:900px;margin:0 auto;}h1{color:#1a3a6b;border-bottom:3px solid #1a3a6b;padding-bottom:8px;}@media print{body{padding:12px;}}</style>
    </head><body>
    <h1>📋 Fichas del equipo — ${team.name}</h1>
    <p style="color:#888;font-size:12px;margin-bottom:20px">${team.category} · ${team.format||"F11"} · ${players.length} jugadores · ${fmtDate(today())}</p>
    ${playerCards}
    <p style="font-size:10px;color:#bbb;margin-top:24px">Canet F.C. · ${fmtDate(today())}</p>
    </body></html>`;

    const blob=new Blob([html],{type:"text/html;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const win=window.open(url,"_blank");
    if(win) setTimeout(()=>{ win.print(); URL.revokeObjectURL(url); },500);
  };

  return <div>
    <div className="sec-title">📋 Fichas del equipo</div>
    <div className="card">
      <div className="fg" style={{marginBottom:12}}>
        <label className="flabel">Equipo</label>
        <select className="fselect" value={selTeam} onChange={e=>setSelTeam(e.target.value)}>
          {teams.map(t=><option key={t.id} value={t.id}>{t.name} ({(t.players||[]).length} jug.)</option>)}
        </select>
      </div>
      <div style={{fontSize:12,color:"#6b7280",marginBottom:12}}>Genera un PDF con la ficha individual de cada jugador del equipo: datos, asistencia, evolución, contacto emergencia y alergias.</div>
      <button className="btn btn-primary" style={{width:"100%",justifyContent:"center"}} onClick={generate}>📄 Generar fichas del equipo</button>
    </div>
  </div>;
}

// ─── CONTENIDO DE LA SESIÓN ───────────────────────────────────
function ContenidoSesionTab({session,team,updateTeam}){
  const blocks=session.contentBlocks||[];
  const [showAdd,setShowAdd]=useState(false);
  const [form,setForm]=useState({type:"",description:"",objectives:[]});
  const [newObj,setNewObj]=useState("");

  const saveBlock=()=>{
    if(!form.type)return;
    const block={id:genId(),...form};
    updateTeam(team.id,t=>({...t,sessions:t.sessions.map(s=>s.id===session.id?{...s,contentBlocks:[...(s.contentBlocks||[]),block]}:s)}));
    setForm({type:"",description:"",objectives:[]});setNewObj("");setShowAdd(false);
  };

  const removeBlock=id=>updateTeam(team.id,t=>({...t,sessions:t.sessions.map(s=>s.id===session.id?{...s,contentBlocks:(s.contentBlocks||[]).filter(b=>b.id!==id)}:s)}));

  const addObj=()=>{
    if(!newObj.trim())return;
    setForm({...form,objectives:[...form.objectives,newObj.trim()]});
    setNewObj("");
  };

  const removeObj=i=>setForm({...form,objectives:form.objectives.filter((_,idx)=>idx!==i)});

  return <div style={{marginTop:8}}>
    <div className="card" style={{marginBottom:10}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
        <div className="card-title" style={{marginBottom:0}}>📋 Ficha de entrenamiento</div>
        <button className="btn btn-primary btn-sm" onClick={()=>setShowAdd(!showAdd)}>+ Bloque</button>
      </div>
      {blocks.length===0&&!showAdd&&<div style={{fontSize:12,color:"#4b5563",textAlign:"center",padding:"12px 0"}}>Sin bloques añadidos. Añade los ejercicios de la sesión.</div>}
      {blocks.map((b,i)=><div key={b.id} style={{background:"#1c1f2e",borderRadius:10,padding:"11px 13px",marginBottom:8}}>
        <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",gap:8}}>
          <div style={{flex:1}}>
            <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:5}}>
              <span style={{background:"#2563eb18",color:"#93c5fd",border:"1px solid #2563eb25",borderRadius:6,padding:"2px 8px",fontSize:11,fontWeight:600}}>{i+1}. {b.type}</span>
            </div>
            {b.description&&<div style={{fontSize:12,color:"#9ca3af",marginBottom:5}}>{b.description}</div>}
            {b.objectives?.length>0&&<div style={{display:"flex",flexWrap:"wrap",gap:4}}>
              {b.objectives.map((o,oi)=><span key={oi} style={{background:"#22c55e15",color:"#22c55e",border:"1px solid #22c55e25",borderRadius:20,padding:"1px 7px",fontSize:10}}>🎯 {o}</span>)}
            </div>}
          </div>
          <button className="btn btn-danger btn-xs" onClick={()=>removeBlock(b.id)}>✕</button>
        </div>
      </div>)}
    </div>

    {showAdd&&<div className="card" style={{borderColor:"#2563eb30"}}>
      <div className="card-title">Nuevo bloque</div>
      <div className="fg" style={{marginBottom:9}}>
        <label className="flabel">Tipo de ejercicio</label>
        <div style={{display:"flex",flexWrap:"wrap",gap:4,marginTop:4}}>
          {EXERCISE_TYPES.map(t=><button key={t} className="btn btn-xs"
            style={{background:form.type===t?"#2563eb22":"#13161f",color:form.type===t?"#2563eb":"#6b7280",border:`1px solid ${form.type===t?"#2563eb":"#252836"}`}}
            onClick={()=>setForm({...form,type:t})}>{t}</button>)}
        </div>
      </div>
      <div className="fg" style={{marginBottom:9}}>
        <label className="flabel">Descripción / Organización</label>
        <input className="finput" style={{fontSize:12}} value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="3vs3+2C, espacio 20x20m, 4min..."/>
      </div>
      <div className="fg" style={{marginBottom:9}}>
        <label className="flabel">Objetivos del bloque</label>
        <div style={{display:"flex",gap:6,marginTop:4}}>
          <input className="finput" style={{fontSize:12}} value={newObj} onChange={e=>setNewObj(e.target.value)} placeholder="Añadir objetivo..." onKeyDown={e=>e.key==="Enter"&&addObj()}/>
          <button className="btn btn-primary btn-sm" onClick={addObj}>+</button>
        </div>
        {form.objectives.map((o,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:7,padding:"5px 0",borderBottom:"1px solid #1a1d2a"}}>
          <span style={{flex:1,fontSize:12,color:"#e2e4f0"}}>🎯 {o}</span>
          <button className="btn btn-danger btn-xs" onClick={()=>removeObj(i)}>✕</button>
        </div>)}
      </div>
      <div style={{display:"flex",gap:7}}>
        <button className="btn btn-primary btn-sm" onClick={saveBlock} disabled={!form.type}>Guardar bloque</button>
        <button className="btn btn-outline btn-sm" onClick={()=>{setShowAdd(false);setForm({type:"",description:"",objectives:[]});}}>Cancelar</button>
      </div>
    </div>}
  </div>;
}

// ─── ADMIN VIEW (Presidenta / Administrativa) ─────────────────
function AdminView({teams,theme,setTheme,logout}){
  const [tab,setTab]=useState("asistencia");
  const [selTeam,setSelTeam]=useState(null);
  const [profileId,setProfileId]=useState(null);

  const tabs=[
    {id:"asistencia",label:"📋 Asistencia"},
    {id:"jugadores", label:"👥 Jugadores"},
  ];

  const team=teams.find(t=>t.id===selTeam);

  if(selTeam&&team){
    if(profileId){
      const player=team.players.find(p=>p.id===profileId);
      if(player) return <div className="app-wrap">
        <div className="header">
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <img src={CLUB_LOGO} style={{width:26,height:26,objectFit:"contain"}}/>
            <div><div style={{fontSize:13,fontWeight:700}}>{team.name}</div><div style={{fontSize:11,color:"#6b7280"}}>Administración</div></div>
          </div>
          <div style={{display:"flex",gap:5}}>
            <button className="btn btn-ghost btn-sm" onClick={()=>setTheme(t=>t==="dark"?"light":"dark")}>{theme==="dark"?"☀️":"🌙"}</button>
            <button className="btn btn-ghost btn-sm" onClick={logout}>Salir</button>
          </div>
        </div>
        <div className="content">
          <div className="back-btn" onClick={()=>setProfileId(null)}>← Volver</div>
          <div className="card" style={{padding:14,marginBottom:11}}>
            <div style={{fontWeight:700,fontSize:17}}>{player.name}{player.number?` · #${player.number}`:""}</div>
            <div style={{fontSize:12,color:"#6b7280",marginTop:2}}>{player.dob?fmtDate(player.dob):"Sin fecha de nacimiento"}</div>
            <div style={{marginTop:8}}>
              <span style={{background:STATE_COLORS[player.state||"Disponible"]+"22",color:STATE_COLORS[player.state||"Disponible"],border:`1px solid ${STATE_COLORS[player.state||"Disponible"]}30`,borderRadius:20,padding:"3px 10px",fontSize:12,fontWeight:600}}>{player.state||"Disponible"}</span>
            </div>
          </div>
          {(player.emergencyName||player.emergencyPhone||player.mutua||player.allergies)&&<div className="card">
            <div className="card-title">🏥 Ficha médica</div>
            {player.emergencyName&&<div className="stat-row"><span style={{color:"#6b7280"}}>Contacto emergencia</span><span style={{fontWeight:600}}>{player.emergencyName}</span></div>}
            {player.emergencyPhone&&<div className="stat-row"><span style={{color:"#6b7280"}}>Teléfono</span><a href={`tel:${player.emergencyPhone}`} style={{color:"#2563eb",fontWeight:600}}>{player.emergencyPhone}</a></div>}
            {player.mutua&&<div className="stat-row"><span style={{color:"#6b7280"}}>Mutua / Seguro</span><span style={{fontWeight:600}}>{player.mutua}</span></div>}
            {player.allergies&&<div className="stat-row"><span style={{color:"#6b7280"}}>Alergias</span><span style={{color:"#ef4444",fontWeight:600}}>⚠️ {player.allergies}</span></div>}
          </div>}
          {(()=>{
            const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))];
            let present=0,absent=0,total=0;
            allS.forEach(s=>{const a=s.attendance?.[player.id];if(!a)return;total++;if(a.state==="present")present++;else if(a.state==="absent")absent++;});
            if(!total)return null;
            return <div className="card">
              <div className="card-title">📊 Asistencia</div>
              <div style={{display:"flex",gap:8}}>
                {[{v:`${Math.round(present/total*100)}%`,l:"Asistencia",c:"#22c55e"},{v:present,l:"Presencias",c:"#22c55e"},{v:absent,l:"Ausencias",c:"#ef4444"},{v:total,l:"Total sesiones",c:"#6b7280"}].map((s,i)=><div key={i} className="stat-box" style={{flex:1,padding:10}}><div className="stat-val" style={{fontSize:16,color:s.c}}>{s.v}</div><div className="stat-lbl">{s.l}</div></div>)}
              </div>
            </div>;
          })()}
        </div>
      </div>;
    }

    return <div className="app-wrap">
      <div className="header">
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <img src={CLUB_LOGO} style={{width:26,height:26,objectFit:"contain"}}/>
          <div><div style={{fontSize:13,fontWeight:700}}>{team.name}</div><div style={{fontSize:11,color:"#6b7280"}}>Administración</div></div>
        </div>
        <div style={{display:"flex",gap:5}}>
          <button className="btn btn-ghost btn-sm" onClick={()=>setTheme(t=>t==="dark"?"light":"dark")}>{theme==="dark"?"☀️":"🌙"}</button>
          <button className="btn btn-ghost btn-sm" onClick={()=>setSelTeam(null)}>← Equipos</button>
          <button className="btn btn-ghost btn-sm" onClick={logout}>Salir</button>
        </div>
      </div>
      <div className="nav">{tabs.map(t=><div key={t.id} className={`nav-tab${tab===t.id?" active":""}`} onClick={()=>setTab(t.id)}>{t.label}</div>)}</div>
      <div className="content">
        {tab==="asistencia"&&<AdminAsistenciaTab team={team}/>}
        {tab==="jugadores"&&<div>
          <div className="sec-title">Jugadores — {team.name}</div>
          {(team.players||[]).length===0&&<div className="empty"><div className="empty-icon">👥</div>Sin jugadores</div>}
          <div style={{display:"flex",flexDirection:"column",gap:6}}>
          {(team.players||[]).map(p=><div key={p.id} style={{display:"flex",alignItems:"center",gap:12,background:"#1c1f2e",borderRadius:10,padding:"12px 14px",cursor:"pointer"}} onClick={()=>setProfileId(p.id)}>
            <div style={{width:36,height:36,borderRadius:"50%",background:"#2563eb22",border:"2px solid #2563eb40",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:700,fontSize:14,color:"#2563eb",flexShrink:0}}>{p.number||"—"}</div>
            <div style={{flex:1,fontWeight:600,fontSize:14}}>{p.name}</div>
            {p.state&&p.state!=="Disponible"&&<span style={{background:STATE_COLORS[p.state]+"22",color:STATE_COLORS[p.state],border:`1px solid ${STATE_COLORS[p.state]}30`,borderRadius:20,padding:"2px 8px",fontSize:11,fontWeight:600}}>{p.state}</span>}
            <div style={{color:"#4b5563",fontSize:16}}>›</div>
          </div>)}
          </div>
        </div>}
      </div>
    </div>;
  }

  return <div className="app-wrap">
    <div className="header">
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <img src={CLUB_LOGO} style={{width:26,height:26,objectFit:"contain"}}/>
        <div><div style={{fontSize:13,fontWeight:700}}>Canet F.C.</div><div style={{fontSize:11,color:"#6b7280"}}>Administración</div></div>
      </div>
      <div style={{display:"flex",gap:5}}>
        <button className="btn btn-ghost btn-sm" onClick={()=>setTheme(t=>t==="dark"?"light":"dark")}>{theme==="dark"?"☀️":"🌙"}</button>
        <button className="btn btn-ghost btn-sm" onClick={logout}>Salir</button>
      </div>
    </div>
    <div className="content">
      <div className="sec-title">Equipos del club</div>
      <div className="alert alert-info" style={{marginBottom:14}}>Selecciona un equipo para ver la asistencia y los perfiles de los jugadores.</div>
      {teams.map(t=>{
        const allS=[...(t.sessions||[]).map(s=>({...s})),...(t.matches||[]).map(s=>({...s}))];
        let pres=0,tot=0;
        allS.forEach(s=>Object.values(s.attendance||{}).forEach(a=>{tot++;if(a.state==="present")pres++;}));
        const pct=tot?Math.round(pres/tot*100):0;
        const pctColor=pct>=75?"#22c55e":pct>=50?"#eab308":"#ef4444";
        return <div key={t.id} style={{background:"#1c1f2e",borderRadius:12,padding:"14px 16px",marginBottom:10,cursor:"pointer",border:"1px solid #252836"}} onClick={()=>setSelTeam(t.id)}>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
            <div>
              <div style={{fontWeight:700,fontSize:15}}>{t.name}</div>
              <div style={{fontSize:12,color:"#6b7280",marginTop:2}}>{t.category} · {(t.players||[]).length} jugadores</div>
            </div>
            <div style={{textAlign:"right"}}>
              <div style={{fontSize:22,fontWeight:700,color:pctColor}}>{pct}%</div>
              <div style={{fontSize:10,color:"#6b7280"}}>asistencia</div>
            </div>
          </div>
          <div style={{background:"#252836",borderRadius:20,height:6,overflow:"hidden"}}>
            <div style={{width:`${pct}%`,height:"100%",background:pctColor,borderRadius:20,transition:"width .3s"}}/>
          </div>
        </div>;
      })}
    </div>
  </div>;
}

// ─── ADMIN ASISTENCIA TAB ─────────────────────────────────────
function AdminAsistenciaTab({team}){
  const [filter,setFilter]=useState("all");
  const allS=[...(team.sessions||[]).map(s=>({...s,stype:"training"})),...(team.matches||[]).map(s=>({...s,stype:"match"}))].sort((a,b)=>b.date.localeCompare(a.date));
  const filtered=filter==="all"?allS:allS.filter(s=>s.stype===filter);

  return <div>
    <div className="sec-title">Asistencia — {team.name}</div>
    <div style={{display:"flex",gap:6,marginBottom:14}}>
      {[{v:"all",l:"Todo"},{v:"training",l:"Entrenos"},{v:"match",l:"Partidos"}].map(f=><button key={f.v} className="btn btn-sm"
        style={{background:filter===f.v?"#2563eb22":"#1c1f2e",border:`1px solid ${filter===f.v?"#2563eb":"#252836"}`,color:filter===f.v?"#2563eb":"#9ca3af"}}
        onClick={()=>setFilter(f.v)}>{f.l}</button>)}
    </div>
    {filtered.length===0&&<div className="empty"><div className="empty-icon">📋</div>Sin sesiones</div>}
    {filtered.map(s=>{
      const atts=Object.entries(s.attendance||{});
      const pres=atts.filter(([,a])=>a.state==="present").length;
      const total=atts.length;
      const pct=total?Math.round(pres/total*100):0;
      return <div key={s.id} className="card-sm" style={{marginBottom:8}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:6}}>
          <div>
            <span style={{fontSize:12,fontWeight:700,color:s.stype==="training"?"#2563eb":"#22c55e"}}>{s.stype==="training"?"🏃":"⚽"} {fmtDate(s.date)}</span>
            <span style={{fontSize:11,color:"#6b7280",marginLeft:8}}>{s.topic||s.rival||""}</span>
          </div>
          <span style={{fontSize:14,fontWeight:700,color:pct>=75?"#22c55e":pct>=50?"#eab308":"#ef4444"}}>{pct}%</span>
        </div>
        <div style={{display:"flex",flexWrap:"wrap",gap:4}}>
          {(team.players||[]).map(p=>{
            const a=s.attendance?.[p.id];
            const state=a?.state||"—";
            const attState=ATT_STATES.find(x=>x.value===state);
            return <div key={p.id} style={{fontSize:10,background:(attState?.color||"#6b7280")+"18",color:attState?.color||"#6b7280",border:`1px solid ${attState?.color||"#6b7280"}25`,borderRadius:6,padding:"2px 6px"}}>
              {p.name.split(" ")[0]} {attState?.icon||"—"}
            </div>;
          })}
        </div>
      </div>;
    })}
  </div>;
}

// ─── INJURY PROFILE MANAGER ──────────────────────────────────
function InjuryProfileManager({player,team,updateTeam}){
  const [tick,setTick]=useState(0); // force re-render after updates

  const freshPlayer=team.players?.find(p=>p.id===player.id)||player;
  const injuries=(freshPlayer.injuries||[]).slice().sort((a,b)=>b.start.localeCompare(a.start));
  const activeInjury=injuries.find(i=>!i.end);
  const pid=player.id;

  const addInjury=()=>{
    const newInj={id:genId(),start:today(),end:"",type:"",mechanism:""};
    updateTeam(team.id,t=>({...t,players:(t.players||[]).map(p=>p.id===pid?
      {...p,state:"Lesionado",injuries:[...(p.injuries||[]),newInj]}:p)}));
    setTick(n=>n+1);
  };

  const giveDischarge=(aid)=>{
    updateTeam(team.id,t=>({...t,players:(t.players||[]).map(p=>p.id===pid?
      {...p,state:"Disponible",injuries:(p.injuries||[]).map(i=>i.id===aid?{...i,end:today()}:i)}:p)}));
    setTick(n=>n+1);
  };

  const removeInjury=(injId)=>{
    updateTeam(team.id,t=>{
      const rem=(t.players.find(p=>p.id===pid)?.injuries||[]).filter(i=>i.id!==injId);
      return{...t,players:(t.players||[]).map(p=>p.id===pid?
        {...p,injuries:rem,state:rem.some(i=>!i.end)?"Lesionado":"Disponible"}:p)};
    });
    setTick(n=>n+1);
  };

  const updateField=(injId,field,val)=>{
    updateTeam(team.id,t=>({...t,players:(t.players||[]).map(p=>p.id===pid?
      {...p,injuries:(p.injuries||[]).map(i=>i.id===injId?{...i,[field]:val}:i)}:p)}));
  };

  return <div className="card" key={tick}>
    <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
      <div className="card-title" style={{marginBottom:0}}>⚕ Lesiones{injuries.length>0?` (${injuries.length})`:""}</div>
      <div style={{display:"flex",gap:6}}>
        {activeInjury&&<button className="btn btn-sm" style={{background:"#22c55e15",color:"#22c55e",border:"1px solid #22c55e30"}}
          onPointerDown={e=>{e.preventDefault();e.stopPropagation();giveDischarge(activeInjury.id);}}>✓ Alta hoy</button>}
        <button className="btn btn-sm" style={{background:"#ef444415",color:"#ef4444",border:"1px solid #ef444430"}}
          onPointerDown={e=>{e.preventDefault();e.stopPropagation();addInjury();}}>+ Nueva lesión</button>
      </div>
    </div>

    {injuries.length===0&&<div style={{fontSize:12,color:"#4b5563",paddingBottom:4}}>Sin lesiones registradas</div>}

    {injuries.map(inj=><div key={inj.id} style={{background:"#13161f",borderRadius:10,padding:"11px 13px",marginBottom:8,border:"1px solid #252836"}}>
      <div style={{display:"flex",alignItems:"flex-start",gap:8}}>
        <div style={{flex:1}}>
          <div style={{display:"flex",alignItems:"center",gap:7,marginBottom:8,flexWrap:"wrap"}}>
            <span style={{fontWeight:700,fontSize:13,color:inj.end?"#22c55e":"#ef4444"}}>{inj.end?"✓ Alta":"🔴 Activa"}</span>
          </div>
          <div style={{display:"flex",gap:8,marginBottom:7,flexWrap:"wrap"}}>
            <div style={{flex:1,minWidth:120}}>
              <label className="flabel">Inicio</label>
              <input type="date" className="finput" style={{fontSize:12}} defaultValue={inj.start}
                onBlur={e=>{if(e.target.value.length===10)updateField(inj.id,"start",e.target.value);}}/>
            </div>
            <div style={{flex:1,minWidth:120}}>
              <label className="flabel">Alta</label>
              <input type="date" className="finput" style={{fontSize:12}} defaultValue={inj.end||""}
                onBlur={e=>{
                  const v=e.target.value;
                  updateTeam(team.id,t=>{
                    const rem=(t.players.find(p=>p.id===pid)?.injuries||[]).map(i=>i.id===inj.id?{...i,end:v}:i);
                    return{...t,players:(t.players||[]).map(p=>p.id===pid?
                      {...p,injuries:rem,state:rem.some(i=>!i.end)?"Lesionado":"Disponible"}:p)};
                  });
                  setTick(n=>n+1);
                }}/>
            </div>
          </div>
          <div style={{marginBottom:6}}>
            <label className="flabel">Tipo / Zona</label>
            <input className="finput" style={{fontSize:12}} defaultValue={inj.type||""}
              placeholder="Ej: Isquiotibiales, Esguince tobillo..."
              onBlur={e=>updateField(inj.id,"type",e.target.value)}/>
          </div>
          <div>
            <label className="flabel">Mecanismo lesional</label>
            <input className="finput" style={{fontSize:12}} defaultValue={inj.mechanism||""}
              placeholder="Sprint sin contacto, entrada rival..."
              onBlur={e=>updateField(inj.id,"mechanism",e.target.value)}/>
          </div>
        </div>
        <button className="btn btn-danger btn-xs" style={{marginTop:4}}
          onPointerDown={e=>{e.preventDefault();e.stopPropagation();removeInjury(inj.id);}}>✕</button>
      </div>
    </div>)}
  </div>;
}
